enum class Enable : uint8_t {
    DISABLED = 0x0,
    ENABLED = 0x1,
};

inline std::string EnableText(Enable tag) {
    switch (tag) {
        case Enable::DISABLED: return "DISABLED";
        case Enable::ENABLED: return "ENABLED";
        default:
            return std::string("Unknown Enable: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class PacketBoundaryFlag : uint8_t {
    FIRST_NON_AUTOMATICALLY_FLUSHABLE = 0x0,
    CONTINUING_FRAGMENT = 0x1,
    FIRST_AUTOMATICALLY_FLUSHABLE = 0x2,
};

inline std::string PacketBoundaryFlagText(PacketBoundaryFlag tag) {
    switch (tag) {
        case PacketBoundaryFlag::FIRST_NON_AUTOMATICALLY_FLUSHABLE: return "FIRST_NON_AUTOMATICALLY_FLUSHABLE";
        case PacketBoundaryFlag::CONTINUING_FRAGMENT: return "CONTINUING_FRAGMENT";
        case PacketBoundaryFlag::FIRST_AUTOMATICALLY_FLUSHABLE: return "FIRST_AUTOMATICALLY_FLUSHABLE";
        default:
            return std::string("Unknown PacketBoundaryFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class BroadcastFlag : uint8_t {
    POINT_TO_POINT = 0x0,
    ACTIVE_PERIPHERAL_BROADCAST = 0x1,
};

inline std::string BroadcastFlagText(BroadcastFlag tag) {
    switch (tag) {
        case BroadcastFlag::POINT_TO_POINT: return "POINT_TO_POINT";
        case BroadcastFlag::ACTIVE_PERIPHERAL_BROADCAST: return "ACTIVE_PERIPHERAL_BROADCAST";
        default:
            return std::string("Unknown BroadcastFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class AclView {
public:
    static AclView Create(pdl::packet::slice const& parent) {
        return AclView(parent);
    }

    uint16_t GetHandle() const {
        _ASSERT_VALID(valid_);
        return handle_;
    }
    
    PacketBoundaryFlag GetPacketBoundaryFlag() const {
        _ASSERT_VALID(valid_);
        return packet_boundary_flag_;
    }
    
    BroadcastFlag GetBroadcastFlag() const {
        _ASSERT_VALID(valid_);
        return broadcast_flag_;
    }
    
    std::vector<uint8_t> GetPayload() const {
        _ASSERT_VALID(valid_);
        return payload_.bytes();
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit AclView(pdl::packet::slice const& parent)
          : bytes_(parent) {
        valid_ = Parse(parent);
    }

    bool Parse(pdl::packet::slice const& parent) {
        // Parse packet field values.
        pdl::packet::slice span = parent;
        uint16_t _payload__size;
        if (span.size() < 4) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        handle_ = (chunk0 >> 0) & 0xfff;
        packet_boundary_flag_ = PacketBoundaryFlag((chunk0 >> 12) & 0x3);
        broadcast_flag_ = BroadcastFlag((chunk0 >> 14) & 0x3);
        _payload__size = span.read_le<uint16_t, 2>();
        if (span.size() < _payload__size) {
            return false;
        }
        payload_ = span.subrange(0, _payload__size);
        span.skip(_payload__size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t handle_{0};
    PacketBoundaryFlag packet_boundary_flag_{PacketBoundaryFlag::FIRST_NON_AUTOMATICALLY_FLUSHABLE};
    BroadcastFlag broadcast_flag_{BroadcastFlag::POINT_TO_POINT};
    pdl::packet::slice payload_;

    
};

class AclBuilder : public pdl::packet::Builder {
public:
    ~AclBuilder() override = default;
    AclBuilder() = default;
    AclBuilder(AclBuilder const&) = default;
    AclBuilder(AclBuilder&&) = default;
    AclBuilder& operator=(AclBuilder const&) = default;
        AclBuilder(uint16_t handle, PacketBoundaryFlag packet_boundary_flag, BroadcastFlag broadcast_flag, std::vector<uint8_t> payload)
        : handle_(handle), packet_boundary_flag_(packet_boundary_flag), broadcast_flag_(broadcast_flag), payload_(std::move(payload)) {
    
}
    static std::unique_ptr<AclBuilder> Create(uint16_t handle, PacketBoundaryFlag packet_boundary_flag, BroadcastFlag broadcast_flag, std::vector<uint8_t> payload) {
    return std::make_unique<AclBuilder>(handle, packet_boundary_flag, broadcast_flag, std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(handle_ & 0xfff) << 0) | (static_cast<uint16_t>(packet_boundary_flag_) << 12) | (static_cast<uint16_t>(broadcast_flag_) << 14));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(payload_.size()) << 0));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 4;
    }

    
    uint16_t handle_{0};
    PacketBoundaryFlag packet_boundary_flag_{PacketBoundaryFlag::FIRST_NON_AUTOMATICALLY_FLUSHABLE};
    BroadcastFlag broadcast_flag_{BroadcastFlag::POINT_TO_POINT};
    std::vector<uint8_t> payload_;
};

enum class PacketStatusFlag : uint8_t {
    CORRECTLY_RECEIVED = 0x0,
    POSSIBLY_INCOMPLETE = 0x1,
    NO_DATA_RECEIVED = 0x2,
    PARTIALLY_LOST = 0x3,
};

inline std::string PacketStatusFlagText(PacketStatusFlag tag) {
    switch (tag) {
        case PacketStatusFlag::CORRECTLY_RECEIVED: return "CORRECTLY_RECEIVED";
        case PacketStatusFlag::POSSIBLY_INCOMPLETE: return "POSSIBLY_INCOMPLETE";
        case PacketStatusFlag::NO_DATA_RECEIVED: return "NO_DATA_RECEIVED";
        case PacketStatusFlag::PARTIALLY_LOST: return "PARTIALLY_LOST";
        default:
            return std::string("Unknown PacketStatusFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class ScoView {
public:
    static ScoView Create(pdl::packet::slice const& parent) {
        return ScoView(parent);
    }

    uint16_t GetHandle() const {
        _ASSERT_VALID(valid_);
        return handle_;
    }
    
    PacketStatusFlag GetPacketStatusFlag() const {
        _ASSERT_VALID(valid_);
        return packet_status_flag_;
    }
    
    std::vector<uint8_t> GetData() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = data_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ScoView(pdl::packet::slice const& parent)
          : bytes_(parent) {
        valid_ = Parse(parent);
    }

    bool Parse(pdl::packet::slice const& parent) {
        // Parse packet field values.
        pdl::packet::slice span = parent;
        uint8_t data_size;
        if (span.size() < 3) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        handle_ = (chunk0 >> 0) & 0xfff;
        packet_status_flag_ = PacketStatusFlag((chunk0 >> 12) & 0x3);
        data_size = span.read_le<uint8_t, 1>();
        if (span.size() < data_size) {
            return false;
        }
        data_ = span.subrange(0, data_size);
        span.skip(data_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t handle_{0};
    PacketStatusFlag packet_status_flag_{PacketStatusFlag::CORRECTLY_RECEIVED};
    pdl::packet::slice data_;

    
};

class ScoBuilder : public pdl::packet::Builder {
public:
    ~ScoBuilder() override = default;
    ScoBuilder() = default;
    ScoBuilder(ScoBuilder const&) = default;
    ScoBuilder(ScoBuilder&&) = default;
    ScoBuilder& operator=(ScoBuilder const&) = default;
        ScoBuilder(uint16_t handle, PacketStatusFlag packet_status_flag, std::vector<uint8_t> data)
        : handle_(handle), packet_status_flag_(packet_status_flag), data_(std::move(data)) {
    
}
    static std::unique_ptr<ScoBuilder> Create(uint16_t handle, PacketStatusFlag packet_status_flag, std::vector<uint8_t> data) {
    return std::make_unique<ScoBuilder>(handle, packet_status_flag, std::move(data));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(handle_ & 0xfff) << 0) | (static_cast<uint16_t>(packet_status_flag_) << 12));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(GetDataSize()) << 0));
        output.insert(output.end(), data_.begin(), data_.end());
    }

    size_t GetSize() const override {
        return GetDataSize() + 3;
    }

    size_t GetDataSize() const {
        return data_.size() * 1;
    }
    
    uint16_t handle_{0};
    PacketStatusFlag packet_status_flag_{PacketStatusFlag::CORRECTLY_RECEIVED};
    std::vector<uint8_t> data_;
};

