class EventBuilder : public pdl::packet::Builder {
public:
    ~EventBuilder() override = default;
    EventBuilder() = default;
    EventBuilder(EventBuilder const&) = default;
    EventBuilder(EventBuilder&&) = default;
    EventBuilder& operator=(EventBuilder const&) = default;
        EventBuilder(EventCode event_code, std::vector<uint8_t> payload)
        : event_code_(event_code), payload_(std::move(payload)) {
    
}
    static std::unique_ptr<EventBuilder> Create(EventCode event_code, std::vector<uint8_t> payload) {
    return std::make_unique<EventBuilder>(event_code, std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_code_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(payload_.size()) << 0));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 2;
    }

    
    EventCode event_code_{EventCode::INQUIRY_COMPLETE};
    std::vector<uint8_t> payload_;
};

