class Lap : public pdl::packet::Builder {
public:
    ~Lap() override = default;
    Lap() = default;
    Lap(Lap const&) = default;
    Lap(Lap&&) = default;
    Lap& operator=(Lap const&) = default;
        explicit Lap(uint8_t lap)
        : lap_(lap) {
    
}

    static bool Parse(pdl::packet::slice& span, Lap* output) {
        uint8_t lap_;
        if (span.size() < 3) {
            return false;
        }
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        lap_ = (chunk0 >> 0) & 0x3f;
        if ((span.read_le<uint16_t, 2>()) != 0x9e8b) {
            return false;
        }
        *output = Lap(lap_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(lap_ & 0x3f) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(40587) << 0));
    }

    size_t GetSize() const override {
        return 3;
    }

    
    std::string ToString() const {
        return "";
    }
    
    uint8_t lap_{0};
};

class InquiryView {
public:
    static InquiryView Create(CommandView const& parent) {
        return InquiryView(parent);
    }

    Lap const& GetLap() const {
        _ASSERT_VALID(valid_);
        return lap_;
    }
    
    uint8_t GetInquiryLength() const {
        _ASSERT_VALID(valid_);
        return inquiry_length_;
    }
    
    uint8_t GetNumResponses() const {
        _ASSERT_VALID(valid_);
        return num_responses_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::INQUIRY;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit InquiryView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::INQUIRY) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (!Lap::Parse(span, &lap_)) {
            return false;
        }
        if (span.size() < 2) {
            return false;
        }
        inquiry_length_ = span.read_le<uint8_t, 1>();
        num_responses_ = span.read_le<uint8_t, 1>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    Lap lap_;
    uint8_t inquiry_length_{0};
    uint8_t num_responses_{0};

    
};

class InquiryBuilder : public CommandBuilder {
public:
    ~InquiryBuilder() override = default;
    InquiryBuilder() = default;
    InquiryBuilder(InquiryBuilder const&) = default;
    InquiryBuilder(InquiryBuilder&&) = default;
    InquiryBuilder& operator=(InquiryBuilder const&) = default;
        InquiryBuilder(Lap lap, uint8_t inquiry_length, uint8_t num_responses)
        : CommandBuilder(OpCode::INQUIRY, std::vector<uint8_t>{}), lap_(std::move(lap)), inquiry_length_(inquiry_length), num_responses_(num_responses) {
    
}
    static std::unique_ptr<InquiryBuilder> Create(Lap lap, uint8_t inquiry_length, uint8_t num_responses) {
    return std::make_unique<InquiryBuilder>(std::move(lap), inquiry_length, num_responses);
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::INQUIRY) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(5) << 0));
        lap_.Serialize(output);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(inquiry_length_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(num_responses_ & 0xff) << 0));
    }

    size_t GetSize() const override {
        return 8;
    }

    
    Lap lap_;
    uint8_t inquiry_length_{0};
    uint8_t num_responses_{0};
};

class InquiryStatusView {
public:
    static InquiryStatusView Create(CommandStatusView const& parent) {
        return InquiryStatusView(parent);
    }

    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_STATUS;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::INQUIRY;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit InquiryStatusView(CommandStatusView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandStatusView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        status_ = parent.status_;
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::INQUIRY) {
            return false;
        }
        
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    uint8_t num_hci_command_packets_{0};

    
};

class InquiryStatusBuilder : public CommandStatusBuilder {
public:
    ~InquiryStatusBuilder() override = default;
    InquiryStatusBuilder() = default;
    InquiryStatusBuilder(InquiryStatusBuilder const&) = default;
    InquiryStatusBuilder(InquiryStatusBuilder&&) = default;
    InquiryStatusBuilder& operator=(InquiryStatusBuilder const&) = default;
        InquiryStatusBuilder(ErrorCode status, uint8_t num_hci_command_packets)
        : CommandStatusBuilder(status, num_hci_command_packets, OpCode::INQUIRY, std::vector<uint8_t>{}) {
    
}
    static std::unique_ptr<InquiryStatusBuilder> Create(ErrorCode status, uint8_t num_hci_command_packets) {
    return std::make_unique<InquiryStatusBuilder>(status, num_hci_command_packets);
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::COMMAND_STATUS) << 0));
        size_t commandstatus_payload_size = 0;
        size_t event_payload_size = 4;
        event_payload_size += commandstatus_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(status_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(num_hci_command_packets_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::INQUIRY) << 0));
    }

    size_t GetSize() const override {
        return 6;
    }

    
    
};

