class PeriodicInquiryModeView {
public:
    static PeriodicInquiryModeView Create(CommandView const& parent) {
        return PeriodicInquiryModeView(parent);
    }

    uint16_t GetMaxPeriodLength() const {
        _ASSERT_VALID(valid_);
        return max_period_length_;
    }
    
    uint16_t GetMinPeriodLength() const {
        _ASSERT_VALID(valid_);
        return min_period_length_;
    }
    
    Lap const& GetLap() const {
        _ASSERT_VALID(valid_);
        return lap_;
    }
    
    uint8_t GetInquiryLength() const {
        _ASSERT_VALID(valid_);
        return inquiry_length_;
    }
    
    uint8_t GetNumResponses() const {
        _ASSERT_VALID(valid_);
        return num_responses_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::PERIODIC_INQUIRY_MODE;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit PeriodicInquiryModeView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::PERIODIC_INQUIRY_MODE) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 4) {
            return false;
        }
        max_period_length_ = span.read_le<uint16_t, 2>();
        min_period_length_ = span.read_le<uint16_t, 2>();
        if (!Lap::Parse(span, &lap_)) {
            return false;
        }
        if (span.size() < 2) {
            return false;
        }
        inquiry_length_ = span.read_le<uint8_t, 1>();
        num_responses_ = span.read_le<uint8_t, 1>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t max_period_length_{0};
    uint16_t min_period_length_{0};
    Lap lap_;
    uint8_t inquiry_length_{0};
    uint8_t num_responses_{0};

    
};

class PeriodicInquiryModeBuilder : public CommandBuilder {
public:
    ~PeriodicInquiryModeBuilder() override = default;
    PeriodicInquiryModeBuilder() = default;
    PeriodicInquiryModeBuilder(PeriodicInquiryModeBuilder const&) = default;
    PeriodicInquiryModeBuilder(PeriodicInquiryModeBuilder&&) = default;
    PeriodicInquiryModeBuilder& operator=(PeriodicInquiryModeBuilder const&) = default;
        PeriodicInquiryModeBuilder(uint16_t max_period_length, uint16_t min_period_length, Lap lap, uint8_t inquiry_length, uint8_t num_responses)
        : CommandBuilder(OpCode::PERIODIC_INQUIRY_MODE, std::vector<uint8_t>{}), max_period_length_(max_period_length), min_period_length_(min_period_length), lap_(std::move(lap)), inquiry_length_(inquiry_length), num_responses_(num_responses) {
    
}
    static std::unique_ptr<PeriodicInquiryModeBuilder> Create(uint16_t max_period_length, uint16_t min_period_length, Lap lap, uint8_t inquiry_length, uint8_t num_responses) {
    return std::make_unique<PeriodicInquiryModeBuilder>(max_period_length, min_period_length, std::move(lap), inquiry_length, num_responses);
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::PERIODIC_INQUIRY_MODE) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(9) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(max_period_length_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(min_period_length_ & 0xffff) << 0));
        lap_.Serialize(output);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(inquiry_length_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(num_responses_ & 0xff) << 0));
    }

    size_t GetSize() const override {
        return 12;
    }

    
    uint16_t max_period_length_{0};
    uint16_t min_period_length_{0};
    Lap lap_;
    uint8_t inquiry_length_{0};
    uint8_t num_responses_{0};
};

