enum class PageScanRepetitionMode : uint8_t {
    R0 = 0x0,
    R1 = 0x1,
    R2 = 0x2,
};

inline std::string PageScanRepetitionModeText(PageScanRepetitionMode tag) {
    switch (tag) {
        case PageScanRepetitionMode::R0: return "R0";
        case PageScanRepetitionMode::R1: return "R1";
        case PageScanRepetitionMode::R2: return "R2";
        default:
            return std::string("Unknown PageScanRepetitionMode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class ClockOffsetValid : uint8_t {
    INVALID = 0x0,
    VALID = 0x1,
};

inline std::string ClockOffsetValidText(ClockOffsetValid tag) {
    switch (tag) {
        case ClockOffsetValid::INVALID: return "INVALID";
        case ClockOffsetValid::VALID: return "VALID";
        default:
            return std::string("Unknown ClockOffsetValid: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class CreateConnectionRoleSwitch : uint8_t {
    REMAIN_CENTRAL = 0x0,
    ALLOW_ROLE_SWITCH = 0x1,
};

inline std::string CreateConnectionRoleSwitchText(CreateConnectionRoleSwitch tag) {
    switch (tag) {
        case CreateConnectionRoleSwitch::REMAIN_CENTRAL: return "REMAIN_CENTRAL";
        case CreateConnectionRoleSwitch::ALLOW_ROLE_SWITCH: return "ALLOW_ROLE_SWITCH";
        default:
            return std::string("Unknown CreateConnectionRoleSwitch: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

