protected:
    explicit CreateConnectionView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::CREATE_CONNECTION) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 7) {
            return false;
        }
        packet_type_ = span.read_le<uint16_t, 2>();
        page_scan_repetition_mode_ = PageScanRepetitionMode(span.read_le<uint8_t, 1>());
        span.skip(1); // skip reserved fields
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        clock_offset_ = (chunk0 >> 0) & 0x7fff;
        clock_offset_valid_ = ClockOffsetValid((chunk0 >> 15) & 0x1);
        allow_role_switch_ = CreateConnectionRoleSwitch(span.read_le<uint8_t, 1>());
        return true;
    }

