enum class DisconnectReason : uint8_t {
    AUTHENTICATION_FAILURE = 0x5,
    REMOTE_USER_TERMINATED_CONNECTION = 0x13,
    REMOTE_DEVICE_TERMINATED_CONNECTION_LOW_RESOURCES = 0x14,
    REMOTE_DEVICE_TERMINATED_CONNECTION_POWER_OFF = 0x15,
    UNSUPPORTED_REMOTE_FEATURE = 0x1a,
    PAIRING_WITH_UNIT_KEY_NOT_SUPPORTED = 0x29,
    UNACCEPTABLE_CONNECTION_PARAMETERS = 0x3b,
};

inline std::string DisconnectReasonText(DisconnectReason tag) {
    switch (tag) {
        case DisconnectReason::AUTHENTICATION_FAILURE: return "AUTHENTICATION_FAILURE";
        case DisconnectReason::REMOTE_USER_TERMINATED_CONNECTION: return "REMOTE_USER_TERMINATED_CONNECTION";
        case DisconnectReason::REMOTE_DEVICE_TERMINATED_CONNECTION_LOW_RESOURCES: return "REMOTE_DEVICE_TERMINATED_CONNECTION_LOW_RESOURCES";
        case DisconnectReason::REMOTE_DEVICE_TERMINATED_CONNECTION_POWER_OFF: return "REMOTE_DEVICE_TERMINATED_CONNECTION_POWER_OFF";
        case DisconnectReason::UNSUPPORTED_REMOTE_FEATURE: return "UNSUPPORTED_REMOTE_FEATURE";
        case DisconnectReason::PAIRING_WITH_UNIT_KEY_NOT_SUPPORTED: return "PAIRING_WITH_UNIT_KEY_NOT_SUPPORTED";
        case DisconnectReason::UNACCEPTABLE_CONNECTION_PARAMETERS: return "UNACCEPTABLE_CONNECTION_PARAMETERS";
        default:
            return std::string("Unknown DisconnectReason: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

