class LinkKeyRequestReplyView {
public:
    static LinkKeyRequestReplyView Create(CommandView const& parent) {
        return LinkKeyRequestReplyView(parent);
    }

    Address const& GetBdAddr() const {
        _ASSERT_VALID(valid_);
        return bd_addr_;
    }
    
    std::array<uint8_t, 16> GetLinkKey() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = link_key_;
        std::array<uint8_t, 16> elements;
        for (int n = 0; n < 16; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LINK_KEY_REQUEST_REPLY;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LinkKeyRequestReplyView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LINK_KEY_REQUEST_REPLY) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 16 * 1) {
            return false;
        }
        link_key_ = span.subrange(0, 16 * 1);
        span.skip(16 * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    Address bd_addr_;
    pdl::packet::slice link_key_;

    
};

