class PinCodeRequestReplyView {
public:
    static PinCodeRequestReplyView Create(CommandView const& parent) {
        return PinCodeRequestReplyView(parent);
    }

    Address const& GetBdAddr() const {
        _ASSERT_VALID(valid_);
        return bd_addr_;
    }
    
    uint8_t GetPinCodeLength() const {
        _ASSERT_VALID(valid_);
        return pin_code_length_;
    }
    
    std::array<uint8_t, 16> GetPinCode() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = pin_code_;
        std::array<uint8_t, 16> elements;
        for (int n = 0; n < 16; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::PIN_CODE_REQUEST_REPLY;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit PinCodeRequestReplyView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::PIN_CODE_REQUEST_REPLY) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 1) {
            return false;
        }
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        pin_code_length_ = (chunk0 >> 0) & 0x1f;
        if (span.size() < 16 * 1) {
            return false;
        }
        pin_code_ = span.subrange(0, 16 * 1);
        span.skip(16 * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    Address bd_addr_;
    uint8_t pin_code_length_{0};
    pdl::packet::slice pin_code_;

    
};

