enum class KeyFlag : uint8_t {
    SEMI_PERMANENT = 0x0,
    TEMPORARY = 0x1,
};

inline std::string KeyFlagText(KeyFlag tag) {
    switch (tag) {
        case KeyFlag::SEMI_PERMANENT: return "SEMI_PERMANENT";
        case KeyFlag::TEMPORARY: return "TEMPORARY";
        default:
            return std::string("Unknown KeyFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

