class ReadLmpHandleCompleteView {
public:
    static ReadLmpHandleCompleteView Create(CommandCompleteView const& parent) {
        return ReadLmpHandleCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    uint8_t GetLmpHandle() const {
        _ASSERT_VALID(valid_);
        return lmp_handle_;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::READ_LMP_HANDLE;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadLmpHandleCompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::READ_LMP_HANDLE) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 8) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        lmp_handle_ = span.read_le<uint8_t, 1>();
        span.skip(4); // skip reserved fields
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    uint16_t connection_handle_{0};
    uint8_t lmp_handle_{0};

    
};

