class QosSetupView {
public:
    static QosSetupView Create(CommandView const& parent) {
        return QosSetupView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    ServiceType GetServiceType() const {
        _ASSERT_VALID(valid_);
        return service_type_;
    }
    
    uint32_t GetTokenRate() const {
        _ASSERT_VALID(valid_);
        return token_rate_;
    }
    
    uint32_t GetPeakBandwidth() const {
        _ASSERT_VALID(valid_);
        return peak_bandwidth_;
    }
    
    uint32_t GetLatency() const {
        _ASSERT_VALID(valid_);
        return latency_;
    }
    
    uint32_t GetDelayVariation() const {
        _ASSERT_VALID(valid_);
        return delay_variation_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::QOS_SETUP;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit QosSetupView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::QOS_SETUP) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 20) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        span.skip(1); // skip reserved fields
        service_type_ = ServiceType(span.read_le<uint8_t, 1>());
        token_rate_ = span.read_le<uint32_t, 4>();
        peak_bandwidth_ = span.read_le<uint32_t, 4>();
        latency_ = span.read_le<uint32_t, 4>();
        delay_variation_ = span.read_le<uint32_t, 4>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    ServiceType service_type_{ServiceType::NO_TRAFFIC};
    uint32_t token_rate_{0};
    uint32_t peak_bandwidth_{0};
    uint32_t latency_{0};
    uint32_t delay_variation_{0};

    
};

