enum class LinkPolicy : uint16_t {
    ENABLE_ROLE_SWITCH = 0x1,
    ENABLE_HOLD_MODE = 0x2,
    ENABLE_SNIFF_MODE = 0x4,
    ENABLE_PARK_MODE = 0x8,
};

inline std::string LinkPolicyText(LinkPolicy tag) {
    switch (tag) {
        case LinkPolicy::ENABLE_ROLE_SWITCH: return "ENABLE_ROLE_SWITCH";
        case LinkPolicy::ENABLE_HOLD_MODE: return "ENABLE_HOLD_MODE";
        case LinkPolicy::ENABLE_SNIFF_MODE: return "ENABLE_SNIFF_MODE";
        case LinkPolicy::ENABLE_PARK_MODE: return "ENABLE_PARK_MODE";
        default:
            return std::string("Unknown LinkPolicy: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

