enum class FlowDirection : uint8_t {
    OUTGOING_FLOW = 0x0,
    INCOMING_FLOW = 0x1,
};

inline std::string FlowDirectionText(FlowDirection tag) {
    switch (tag) {
        case FlowDirection::OUTGOING_FLOW: return "OUTGOING_FLOW";
        case FlowDirection::INCOMING_FLOW: return "INCOMING_FLOW";
        default:
            return std::string("Unknown FlowDirection: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

