enum class FilterType : uint8_t {
    CLEAR_ALL_FILTERS = 0x0,
    INQUIRY_RESULT = 0x1,
    CONNECTION_SETUP = 0x2,
};

inline std::string FilterTypeText(FilterType tag) {
    switch (tag) {
        case FilterType::CLEAR_ALL_FILTERS: return "CLEAR_ALL_FILTERS";
        case FilterType::INQUIRY_RESULT: return "INQUIRY_RESULT";
        case FilterType::CONNECTION_SETUP: return "CONNECTION_SETUP";
        default:
            return std::string("Unknown FilterType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

