enum class PinType : uint8_t {
    VARIABLE = 0x0,
    FIXED = 0x1,
};

inline std::string PinTypeText(PinType tag) {
    switch (tag) {
        case PinType::VARIABLE: return "VARIABLE";
        case PinType::FIXED: return "FIXED";
        default:
            return std::string("Unknown PinType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

