class KeyAndAddress : public pdl::packet::Builder {
public:
    ~KeyAndAddress() override = default;
    KeyAndAddress() = default;
    KeyAndAddress(KeyAndAddress const&) = default;
    KeyAndAddress(KeyAndAddress&&) = default;
    KeyAndAddress& operator=(KeyAndAddress const&) = default;
        KeyAndAddress(Address address, std::array<uint8_t, 16> link_key)
        : address_(std::move(address)), link_key_(std::move(link_key)) {
    
}

    static bool Parse(pdl::packet::slice& span, KeyAndAddress* output) {
        Address address_;
        std::array<uint8_t, 16> link_key_;
        if (!Address::Parse(span, &address_)) {
            return false;
        }
        if (span.size() < 16 * 1) {
            return false;
        }
        for (size_t n = 0; n < 16; n++) {
            link_key_[n] = span.read_le<uint8_t, 1>();
        }
        *output = KeyAndAddress(std::move(address_), std::move(link_key_));
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        address_.Serialize(output);
        output.insert(output.end(), link_key_.begin(), link_key_.end());
    }

    size_t GetSize() const override {
        return 22;
    }

    size_t GetLinkKeySize() const {
        return 16;
    }
    
    std::string ToString() const {
        return "";
    }
    
    Address address_;
    std::array<uint8_t, 16> link_key_;
};

class WriteStoredLinkKeyView {
public:
    static WriteStoredLinkKeyView Create(CommandView const& parent) {
        return WriteStoredLinkKeyView(parent);
    }

    std::vector<KeyAndAddress> GetKeysToWrite() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = keys_to_write_;
        std::vector<KeyAndAddress> elements;
        for (;;) {
            KeyAndAddress element;
            if (!KeyAndAddress::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::WRITE_STORED_LINK_KEY;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit WriteStoredLinkKeyView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::WRITE_STORED_LINK_KEY) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t keys_to_write_count;
        if (span.size() < 1) {
            return false;
        }
        keys_to_write_count = span.read_le<uint8_t, 1>();
        if (span.size() < keys_to_write_count * 22) {
            return false;
        }
        keys_to_write_ = span.subrange(0, keys_to_write_count * 22);
        span.skip(keys_to_write_count * 22);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    pdl::packet::slice keys_to_write_;

    
};

class WriteStoredLinkKeyBuilder : public CommandBuilder {
public:
    ~WriteStoredLinkKeyBuilder() override = default;
    WriteStoredLinkKeyBuilder() = default;
    WriteStoredLinkKeyBuilder(WriteStoredLinkKeyBuilder const&) = default;
    WriteStoredLinkKeyBuilder(WriteStoredLinkKeyBuilder&&) = default;
    WriteStoredLinkKeyBuilder& operator=(WriteStoredLinkKeyBuilder const&) = default;
        explicit WriteStoredLinkKeyBuilder(std::vector<KeyAndAddress> keys_to_write)
        : CommandBuilder(OpCode::WRITE_STORED_LINK_KEY, std::vector<uint8_t>{}), keys_to_write_(std::move(keys_to_write)) {
    
}
    static std::unique_ptr<WriteStoredLinkKeyBuilder> Create(std::vector<KeyAndAddress> keys_to_write) {
    return std::make_unique<WriteStoredLinkKeyBuilder>(std::move(keys_to_write));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::WRITE_STORED_LINK_KEY) << 0));
        size_t command_payload_size = 1;
        command_payload_size += GetKeysToWriteSize();
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(command_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(keys_to_write_.size()) << 0));
        for (size_t n = 0; n < keys_to_write_.size(); n++) {
            keys_to_write_[n].Serialize(output);
        }
    }

    size_t GetSize() const override {
        return GetKeysToWriteSize() + 4;
    }

    size_t GetKeysToWriteSize() const {
        return keys_to_write_.size() * 22;
    }
    
    std::vector<KeyAndAddress> keys_to_write_;
};

