enum class ScanEnable : uint8_t {
    NO_SCANS = 0x0,
    INQUIRY_SCAN_ONLY = 0x1,
    PAGE_SCAN_ONLY = 0x2,
    INQUIRY_AND_PAGE_SCAN = 0x3,
};

inline std::string ScanEnableText(ScanEnable tag) {
    switch (tag) {
        case ScanEnable::NO_SCANS: return "NO_SCANS";
        case ScanEnable::INQUIRY_SCAN_ONLY: return "INQUIRY_SCAN_ONLY";
        case ScanEnable::PAGE_SCAN_ONLY: return "PAGE_SCAN_ONLY";
        case ScanEnable::INQUIRY_AND_PAGE_SCAN: return "INQUIRY_AND_PAGE_SCAN";
        default:
            return std::string("Unknown ScanEnable: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

