enum class HoldModeActivity : uint8_t {
    MAINTAIN_CURRENT_POWER_STATE = 0x0,
    SUSPEND_PAGE_SCAN = 0x1,
    SUSPEND_INQUIRY_SCAN = 0x2,
    SUSPEND_PERIODIC_INQUIRY = 0x3,
};

inline std::string HoldModeActivityText(HoldModeActivity tag) {
    switch (tag) {
        case HoldModeActivity::MAINTAIN_CURRENT_POWER_STATE: return "MAINTAIN_CURRENT_POWER_STATE";
        case HoldModeActivity::SUSPEND_PAGE_SCAN: return "SUSPEND_PAGE_SCAN";
        case HoldModeActivity::SUSPEND_INQUIRY_SCAN: return "SUSPEND_INQUIRY_SCAN";
        case HoldModeActivity::SUSPEND_PERIODIC_INQUIRY: return "SUSPEND_PERIODIC_INQUIRY";
        default:
            return std::string("Unknown HoldModeActivity: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

