enum class TransmitPowerLevelType : uint8_t {
    CURRENT = 0x0,
    MAXIMUM = 0x1,
};

inline std::string TransmitPowerLevelTypeText(TransmitPowerLevelType tag) {
    switch (tag) {
        case TransmitPowerLevelType::CURRENT: return "CURRENT";
        case TransmitPowerLevelType::MAXIMUM: return "MAXIMUM";
        default:
            return std::string("Unknown TransmitPowerLevelType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class ReadTransmitPowerLevelView {
public:
    static ReadTransmitPowerLevelView Create(CommandView const& parent) {
        return ReadTransmitPowerLevelView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    TransmitPowerLevelType GetTransmitPowerLevelType() const {
        _ASSERT_VALID(valid_);
        return transmit_power_level_type_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::READ_TRANSMIT_POWER_LEVEL;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadTransmitPowerLevelView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::READ_TRANSMIT_POWER_LEVEL) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 3) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        transmit_power_level_type_ = TransmitPowerLevelType(span.read_le<uint8_t, 1>());
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    TransmitPowerLevelType transmit_power_level_type_{TransmitPowerLevelType::CURRENT};

    
};

