class CompletedPackets : public pdl::packet::Builder {
public:
    ~CompletedPackets() override = default;
    CompletedPackets() = default;
    CompletedPackets(CompletedPackets const&) = default;
    CompletedPackets(CompletedPackets&&) = default;
    CompletedPackets& operator=(CompletedPackets const&) = default;
        CompletedPackets(uint16_t connection_handle, uint16_t host_num_of_completed_packets)
        : connection_handle_(connection_handle), host_num_of_completed_packets_(host_num_of_completed_packets) {
    
}

    static bool Parse(pdl::packet::slice& span, CompletedPackets* output) {
        uint16_t connection_handle_;
        uint16_t host_num_of_completed_packets_;
        if (span.size() < 4) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        host_num_of_completed_packets_ = span.read_le<uint16_t, 2>();
        *output = CompletedPackets(connection_handle_, host_num_of_completed_packets_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xfff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(host_num_of_completed_packets_ & 0xffff) << 0));
    }

    size_t GetSize() const override {
        return 4;
    }

    
    std::string ToString() const {
        return "";
    }
    
    uint16_t connection_handle_{0};
    uint16_t host_num_of_completed_packets_{0};
};

class HostNumCompletedPacketsView {
public:
    static HostNumCompletedPacketsView Create(CommandView const& parent) {
        return HostNumCompletedPacketsView(parent);
    }

    std::vector<CompletedPackets> GetCompletedPackets() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = completed_packets_;
        std::vector<CompletedPackets> elements;
        for (;;) {
            CompletedPackets element;
            if (!CompletedPackets::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::HOST_NUMBER_OF_COMPLETED_PACKETS;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit HostNumCompletedPacketsView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::HOST_NUMBER_OF_COMPLETED_PACKETS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t completed_packets_count;
        if (span.size() < 1) {
            return false;
        }
        completed_packets_count = span.read_le<uint8_t, 1>();
        if (span.size() < completed_packets_count * 4) {
            return false;
        }
        completed_packets_ = span.subrange(0, completed_packets_count * 4);
        span.skip(completed_packets_count * 4);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    pdl::packet::slice completed_packets_;

    
};

class HostNumCompletedPacketsBuilder : public CommandBuilder {
public:
    ~HostNumCompletedPacketsBuilder() override = default;
    HostNumCompletedPacketsBuilder() = default;
    HostNumCompletedPacketsBuilder(HostNumCompletedPacketsBuilder const&) = default;
    HostNumCompletedPacketsBuilder(HostNumCompletedPacketsBuilder&&) = default;
    HostNumCompletedPacketsBuilder& operator=(HostNumCompletedPacketsBuilder const&) = default;
        explicit HostNumCompletedPacketsBuilder(std::vector<CompletedPackets> completed_packets)
        : CommandBuilder(OpCode::HOST_NUMBER_OF_COMPLETED_PACKETS, std::vector<uint8_t>{}), completed_packets_(std::move(completed_packets)) {
    
}
    static std::unique_ptr<HostNumCompletedPacketsBuilder> Create(std::vector<CompletedPackets> completed_packets) {
    return std::make_unique<HostNumCompletedPacketsBuilder>(std::move(completed_packets));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::HOST_NUMBER_OF_COMPLETED_PACKETS) << 0));
        size_t command_payload_size = 1;
        command_payload_size += GetCompletedPacketsSize();
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(command_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(completed_packets_.size()) << 0));
        for (size_t n = 0; n < completed_packets_.size(); n++) {
            completed_packets_[n].Serialize(output);
        }
    }

    size_t GetSize() const override {
        return GetCompletedPacketsSize() + 4;
    }

    size_t GetCompletedPacketsSize() const {
        return completed_packets_.size() * 4;
    }
    
    std::vector<CompletedPackets> completed_packets_;
};

