enum class FecRequired : uint8_t {
    NOT_REQUIRED = 0x0,
    REQUIRED = 0x1,
};

inline std::string FecRequiredText(FecRequired tag) {
    switch (tag) {
        case FecRequired::NOT_REQUIRED: return "NOT_REQUIRED";
        case FecRequired::REQUIRED: return "REQUIRED";
        default:
            return std::string("Unknown FecRequired: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

