class ReadExtendedInquiryResponseCompleteView {
public:
    static ReadExtendedInquiryResponseCompleteView Create(CommandCompleteView const& parent) {
        return ReadExtendedInquiryResponseCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    FecRequired GetFecRequired() const {
        _ASSERT_VALID(valid_);
        return fec_required_;
    }
    
    std::array<uint8_t, 240> GetExtendedInquiryResponse() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = extended_inquiry_response_;
        std::array<uint8_t, 240> elements;
        for (int n = 0; n < 240; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::READ_EXTENDED_INQUIRY_RESPONSE;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadExtendedInquiryResponseCompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::READ_EXTENDED_INQUIRY_RESPONSE) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 2) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        fec_required_ = FecRequired(span.read_le<uint8_t, 1>());
        if (span.size() < 240 * 1) {
            return false;
        }
        extended_inquiry_response_ = span.subrange(0, 240 * 1);
        span.skip(240 * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    FecRequired fec_required_{FecRequired::NOT_REQUIRED};
    pdl::packet::slice extended_inquiry_response_;

    
};

