class ReadLocalOobDataCompleteView {
public:
    static ReadLocalOobDataCompleteView Create(CommandCompleteView const& parent) {
        return ReadLocalOobDataCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    std::array<uint8_t, 16> GetC() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = c_;
        std::array<uint8_t, 16> elements;
        for (int n = 0; n < 16; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    std::array<uint8_t, 16> GetR() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = r_;
        std::array<uint8_t, 16> elements;
        for (int n = 0; n < 16; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::READ_LOCAL_OOB_DATA;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadLocalOobDataCompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::READ_LOCAL_OOB_DATA) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 1) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        if (span.size() < 16 * 1) {
            return false;
        }
        c_ = span.subrange(0, 16 * 1);
        span.skip(16 * 1);
        if (span.size() < 16 * 1) {
            return false;
        }
        r_ = span.subrange(0, 16 * 1);
        span.skip(16 * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    pdl::packet::slice c_;
    pdl::packet::slice r_;

    
};

