enum class KeypressNotificationType : uint8_t {
    ENTRY_STARTED = 0x0,
    DIGIT_ENTERED = 0x1,
    DIGIT_ERASED = 0x2,
    CLEARED = 0x3,
    ENTRY_COMPLETED = 0x4,
};

inline std::string KeypressNotificationTypeText(KeypressNotificationType tag) {
    switch (tag) {
        case KeypressNotificationType::ENTRY_STARTED: return "ENTRY_STARTED";
        case KeypressNotificationType::DIGIT_ENTERED: return "DIGIT_ENTERED";
        case KeypressNotificationType::DIGIT_ERASED: return "DIGIT_ERASED";
        case KeypressNotificationType::CLEARED: return "CLEARED";
        case KeypressNotificationType::ENTRY_COMPLETED: return "ENTRY_COMPLETED";
        default:
            return std::string("Unknown KeypressNotificationType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

