enum class DataPathDirection : uint8_t {
    INPUT = 0x0,
    OUTPUT = 0x1,
};

inline std::string DataPathDirectionText(DataPathDirection tag) {
    switch (tag) {
        case DataPathDirection::INPUT: return "INPUT";
        case DataPathDirection::OUTPUT: return "OUTPUT";
        default:
            return std::string("Unknown DataPathDirection: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class ConfigureDataPathView {
public:
    static ConfigureDataPathView Create(CommandView const& parent) {
        return ConfigureDataPathView(parent);
    }

    DataPathDirection GetDataPathDirection() const {
        _ASSERT_VALID(valid_);
        return data_path_direction_;
    }
    
    uint8_t GetDataPathId() const {
        _ASSERT_VALID(valid_);
        return data_path_id_;
    }
    
    std::vector<uint8_t> GetVendorSpecificConfig() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = vendor_specific_config_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::CONFIGURE_DATA_PATH;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ConfigureDataPathView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::CONFIGURE_DATA_PATH) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t vendor_specific_config_size;
        if (span.size() < 3) {
            return false;
        }
        data_path_direction_ = DataPathDirection(span.read_le<uint8_t, 1>());
        data_path_id_ = span.read_le<uint8_t, 1>();
        vendor_specific_config_size = span.read_le<uint8_t, 1>();
        if (span.size() < vendor_specific_config_size) {
            return false;
        }
        vendor_specific_config_ = span.subrange(0, vendor_specific_config_size);
        span.skip(vendor_specific_config_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    DataPathDirection data_path_direction_{DataPathDirection::INPUT};
    uint8_t data_path_id_{0};
    pdl::packet::slice vendor_specific_config_;

    
};

