enum class HciVersion : uint8_t {
    V_1_0B = 0x0,
    V_1_1 = 0x1,
    V_1_2 = 0x2,
    V_2_0 = 0x3,
    V_2_1 = 0x4,
    V_3_0 = 0x5,
    V_4_0 = 0x6,
    V_4_1 = 0x7,
    V_4_2 = 0x8,
    V_5_0 = 0x9,
    V_5_1 = 0xa,
    V_5_2 = 0xb,
    V_5_3 = 0xc,
    V_5_4 = 0xd,
};

inline std::string HciVersionText(HciVersion tag) {
    switch (tag) {
        case HciVersion::V_1_0B: return "V_1_0B";
        case HciVersion::V_1_1: return "V_1_1";
        case HciVersion::V_1_2: return "V_1_2";
        case HciVersion::V_2_0: return "V_2_0";
        case HciVersion::V_2_1: return "V_2_1";
        case HciVersion::V_3_0: return "V_3_0";
        case HciVersion::V_4_0: return "V_4_0";
        case HciVersion::V_4_1: return "V_4_1";
        case HciVersion::V_4_2: return "V_4_2";
        case HciVersion::V_5_0: return "V_5_0";
        case HciVersion::V_5_1: return "V_5_1";
        case HciVersion::V_5_2: return "V_5_2";
        case HciVersion::V_5_3: return "V_5_3";
        case HciVersion::V_5_4: return "V_5_4";
        default:
            return std::string("Unknown HciVersion: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

