class LocalVersionInformation : public pdl::packet::Builder {
public:
    ~LocalVersionInformation() override = default;
    LocalVersionInformation() = default;
    LocalVersionInformation(LocalVersionInformation const&) = default;
    LocalVersionInformation(LocalVersionInformation&&) = default;
    LocalVersionInformation& operator=(LocalVersionInformation const&) = default;
        LocalVersionInformation(HciVersion hci_version, uint16_t hci_revision, LmpVersion lmp_version, uint16_t manufacturer_name, uint16_t lmp_subversion)
        : hci_version_(hci_version), hci_revision_(hci_revision), lmp_version_(lmp_version), manufacturer_name_(manufacturer_name), lmp_subversion_(lmp_subversion) {
    
}

    static bool Parse(pdl::packet::slice& span, LocalVersionInformation* output) {
        HciVersion hci_version_;
        uint16_t hci_revision_;
        LmpVersion lmp_version_;
        uint16_t manufacturer_name_;
        uint16_t lmp_subversion_;
        if (span.size() < 8) {
            return false;
        }
        hci_version_ = HciVersion(span.read_le<uint8_t, 1>());
        hci_revision_ = span.read_le<uint16_t, 2>();
        lmp_version_ = LmpVersion(span.read_le<uint8_t, 1>());
        manufacturer_name_ = span.read_le<uint16_t, 2>();
        lmp_subversion_ = span.read_le<uint16_t, 2>();
        *output = LocalVersionInformation(hci_version_, hci_revision_, lmp_version_, manufacturer_name_, lmp_subversion_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(hci_version_) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(hci_revision_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(lmp_version_) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(manufacturer_name_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(lmp_subversion_ & 0xffff) << 0));
    }

    size_t GetSize() const override {
        return 8;
    }

    
    std::string ToString() const {
        return "";
    }
    
    HciVersion hci_version_{HciVersion::V_1_0B};
    uint16_t hci_revision_{0};
    LmpVersion lmp_version_{LmpVersion::V_1_0B};
    uint16_t manufacturer_name_{0};
    uint16_t lmp_subversion_{0};
};

