class ReadLocalSupportedCommandsCompleteView {
public:
    static ReadLocalSupportedCommandsCompleteView Create(CommandCompleteView const& parent) {
        return ReadLocalSupportedCommandsCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    std::array<uint8_t, 64> GetSupportedCommands() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = supported_commands_;
        std::array<uint8_t, 64> elements;
        for (int n = 0; n < 64; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::READ_LOCAL_SUPPORTED_COMMANDS;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadLocalSupportedCommandsCompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::READ_LOCAL_SUPPORTED_COMMANDS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 1) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        if (span.size() < 64 * 1) {
            return false;
        }
        supported_commands_ = span.subrange(0, 64 * 1);
        span.skip(64 * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    pdl::packet::slice supported_commands_;

    
};

