class ReadLocalSupportedCodecsV2CompleteView {
public:
    static ReadLocalSupportedCodecsV2CompleteView Create(CommandCompleteView const& parent) {
        return ReadLocalSupportedCodecsV2CompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    std::vector<CodecConfiguration> GetSupportedCodecs() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = supported_codecs_;
        std::vector<CodecConfiguration> elements;
        for (;;) {
            CodecConfiguration element;
            if (!CodecConfiguration::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    std::vector<VendorCodecConfiguration> GetVendorSpecificCodecs() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = vendor_specific_codecs_;
        std::vector<VendorCodecConfiguration> elements;
        for (;;) {
            VendorCodecConfiguration element;
            if (!VendorCodecConfiguration::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::READ_LOCAL_SUPPORTED_CODECS_V2;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ReadLocalSupportedCodecsV2CompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::READ_LOCAL_SUPPORTED_CODECS_V2) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t supported_codecs_count;
        uint8_t vendor_specific_codecs_count;
        if (span.size() < 2) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        supported_codecs_count = span.read_le<uint8_t, 1>();
        if (span.size() < supported_codecs_count * 2) {
            return false;
        }
        supported_codecs_ = span.subrange(0, supported_codecs_count * 2);
        span.skip(supported_codecs_count * 2);
        if (span.size() < 1) {
            return false;
        }
        vendor_specific_codecs_count = span.read_le<uint8_t, 1>();
        if (span.size() < vendor_specific_codecs_count * 5) {
            return false;
        }
        vendor_specific_codecs_ = span.subrange(0, vendor_specific_codecs_count * 5);
        span.skip(vendor_specific_codecs_count * 5);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    pdl::packet::slice supported_codecs_;
    pdl::packet::slice vendor_specific_codecs_;

    
};

