class LeSetAdvertisingParametersView {
public:
    static LeSetAdvertisingParametersView Create(CommandView const& parent) {
        return LeSetAdvertisingParametersView(parent);
    }

    uint16_t GetAdvertisingIntervalMin() const {
        _ASSERT_VALID(valid_);
        return advertising_interval_min_;
    }
    
    uint16_t GetAdvertisingIntervalMax() const {
        _ASSERT_VALID(valid_);
        return advertising_interval_max_;
    }
    
    AdvertisingType GetAdvertisingType() const {
        _ASSERT_VALID(valid_);
        return advertising_type_;
    }
    
    OwnAddressType GetOwnAddressType() const {
        _ASSERT_VALID(valid_);
        return own_address_type_;
    }
    
    PeerAddressType GetPeerAddressType() const {
        _ASSERT_VALID(valid_);
        return peer_address_type_;
    }
    
    Address const& GetPeerAddress() const {
        _ASSERT_VALID(valid_);
        return peer_address_;
    }
    
    uint8_t GetAdvertisingChannelMap() const {
        _ASSERT_VALID(valid_);
        return advertising_channel_map_;
    }
    
    AdvertisingFilterPolicy GetAdvertisingFilterPolicy() const {
        _ASSERT_VALID(valid_);
        return advertising_filter_policy_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SET_ADVERTISING_PARAMETERS;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetAdvertisingParametersView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SET_ADVERTISING_PARAMETERS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 7) {
            return false;
        }
        advertising_interval_min_ = span.read_le<uint16_t, 2>();
        advertising_interval_max_ = span.read_le<uint16_t, 2>();
        advertising_type_ = AdvertisingType(span.read_le<uint8_t, 1>());
        own_address_type_ = OwnAddressType(span.read_le<uint8_t, 1>());
        peer_address_type_ = PeerAddressType(span.read_le<uint8_t, 1>());
        if (!Address::Parse(span, &peer_address_)) {
            return false;
        }
        if (span.size() < 2) {
            return false;
        }
        advertising_channel_map_ = span.read_le<uint8_t, 1>();
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        advertising_filter_policy_ = AdvertisingFilterPolicy((chunk0 >> 0) & 0x3);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t advertising_interval_min_{0};
    uint16_t advertising_interval_max_{0};
    AdvertisingType advertising_type_{AdvertisingType::ADV_IND};
    OwnAddressType own_address_type_{OwnAddressType::PUBLIC_DEVICE_ADDRESS};
    PeerAddressType peer_address_type_{PeerAddressType::PUBLIC_DEVICE_OR_IDENTITY_ADDRESS};
    Address peer_address_;
    uint8_t advertising_channel_map_{0};
    AdvertisingFilterPolicy advertising_filter_policy_{AdvertisingFilterPolicy::ALL_DEVICES};

    
};

