enum class FilterAcceptListAddressType : uint8_t {
    PUBLIC = 0x0,
    RANDOM = 0x1,
    ANONYMOUS_ADVERTISERS = 0xff,
};

inline std::string FilterAcceptListAddressTypeText(FilterAcceptListAddressType tag) {
    switch (tag) {
        case FilterAcceptListAddressType::PUBLIC: return "PUBLIC";
        case FilterAcceptListAddressType::RANDOM: return "RANDOM";
        case FilterAcceptListAddressType::ANONYMOUS_ADVERTISERS: return "ANONYMOUS_ADVERTISERS";
        default:
            return std::string("Unknown FilterAcceptListAddressType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

