        connection_interval_min_ = span.read_le<uint16_t, 2>();
        connection_interval_max_ = span.read_le<uint16_t, 2>();
        max_latency_ = span.read_le<uint16_t, 2>();
        supervision_timeout_ = span.read_le<uint16_t, 2>();
        min_ce_length_ = span.read_le<uint16_t, 2>();
