enum class LeTestPayload : uint8_t {
    PRBS9 = 0x0,
    REPEATED_F0 = 0x1,
    REPEATED_AA = 0x2,
    PRBS15 = 0x3,
    REPEATED_FF = 0x4,
    REPEATED_00 = 0x5,
    REPEATED_0F = 0x6,
    REPEATED_55 = 0x7,
};

inline std::string LeTestPayloadText(LeTestPayload tag) {
    switch (tag) {
        case LeTestPayload::PRBS9: return "PRBS9";
        case LeTestPayload::REPEATED_F0: return "REPEATED_F0";
        case LeTestPayload::REPEATED_AA: return "REPEATED_AA";
        case LeTestPayload::PRBS15: return "PRBS15";
        case LeTestPayload::REPEATED_FF: return "REPEATED_FF";
        case LeTestPayload::REPEATED_00: return "REPEATED_00";
        case LeTestPayload::REPEATED_0F: return "REPEATED_0F";
        case LeTestPayload::REPEATED_55: return "REPEATED_55";
        default:
            return std::string("Unknown LeTestPayload: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

