enum class Operation : uint8_t {
    INTERMEDIATE_FRAGMENT = 0x0,
    FIRST_FRAGMENT = 0x1,
    LAST_FRAGMENT = 0x2,
    COMPLETE_ADVERTISEMENT = 0x3,
    UNCHANGED_DATA = 0x4,
};

inline std::string OperationText(Operation tag) {
    switch (tag) {
        case Operation::INTERMEDIATE_FRAGMENT: return "INTERMEDIATE_FRAGMENT";
        case Operation::FIRST_FRAGMENT: return "FIRST_FRAGMENT";
        case Operation::LAST_FRAGMENT: return "LAST_FRAGMENT";
        case Operation::COMPLETE_ADVERTISEMENT: return "COMPLETE_ADVERTISEMENT";
        case Operation::UNCHANGED_DATA: return "UNCHANGED_DATA";
        default:
            return std::string("Unknown Operation: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class FragmentPreference : uint8_t {
    CONTROLLER_MAY_FRAGMENT = 0x0,
    CONTROLLER_SHOULD_NOT = 0x1,
};

inline std::string FragmentPreferenceText(FragmentPreference tag) {
    switch (tag) {
        case FragmentPreference::CONTROLLER_MAY_FRAGMENT: return "CONTROLLER_MAY_FRAGMENT";
        case FragmentPreference::CONTROLLER_SHOULD_NOT: return "CONTROLLER_SHOULD_NOT";
        default:
            return std::string("Unknown FragmentPreference: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class LeSetExtendedAdvertisingDataView {
public:
    static LeSetExtendedAdvertisingDataView Create(CommandView const& parent) {
        return LeSetExtendedAdvertisingDataView(parent);
    }

    uint8_t GetAdvertisingHandle() const {
        _ASSERT_VALID(valid_);
        return advertising_handle_;
    }
    
    Operation GetOperation() const {
        _ASSERT_VALID(valid_);
        return operation_;
    }
    
    FragmentPreference GetFragmentPreference() const {
        _ASSERT_VALID(valid_);
        return fragment_preference_;
    }
    
    std::vector<uint8_t> GetAdvertisingData() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = advertising_data_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SET_EXTENDED_ADVERTISING_DATA;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetExtendedAdvertisingDataView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SET_EXTENDED_ADVERTISING_DATA) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t advertising_data_size;
        if (span.size() < 4) {
            return false;
        }
        advertising_handle_ = span.read_le<uint8_t, 1>();
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        operation_ = Operation((chunk0 >> 0) & 0x7);
        uint8_t chunk1 = span.read_le<uint8_t, 1>();
        fragment_preference_ = FragmentPreference((chunk1 >> 0) & 0x1);
        advertising_data_size = span.read_le<uint8_t, 1>();
        if (span.size() < advertising_data_size) {
            return false;
        }
        advertising_data_ = span.subrange(0, advertising_data_size);
        span.skip(advertising_data_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t advertising_handle_{0};
    Operation operation_{Operation::INTERMEDIATE_FRAGMENT};
    FragmentPreference fragment_preference_{FragmentPreference::CONTROLLER_MAY_FRAGMENT};
    pdl::packet::slice advertising_data_;

    
};

