class LeSetPeriodicAdvertisingDataView {
public:
    static LeSetPeriodicAdvertisingDataView Create(CommandView const& parent) {
        return LeSetPeriodicAdvertisingDataView(parent);
    }

    uint8_t GetAdvertisingHandle() const {
        _ASSERT_VALID(valid_);
        return advertising_handle_;
    }
    
    Operation GetOperation() const {
        _ASSERT_VALID(valid_);
        return operation_;
    }
    
    std::vector<uint8_t> GetAdvertisingData() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = advertising_data_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SET_PERIODIC_ADVERTISING_DATA;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetPeriodicAdvertisingDataView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SET_PERIODIC_ADVERTISING_DATA) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t advertising_data_size;
        if (span.size() < 3) {
            return false;
        }
        advertising_handle_ = span.read_le<uint8_t, 1>();
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        operation_ = Operation((chunk0 >> 0) & 0x7);
        advertising_data_size = span.read_le<uint8_t, 1>();
        if (span.size() < advertising_data_size) {
            return false;
        }
        advertising_data_ = span.subrange(0, advertising_data_size);
        span.skip(advertising_data_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t advertising_handle_{0};
    Operation operation_{Operation::INTERMEDIATE_FRAGMENT};
    pdl::packet::slice advertising_data_;

    
};

