class LeSetPeriodicAdvertisingEnableView {
public:
    static LeSetPeriodicAdvertisingEnableView Create(CommandView const& parent) {
        return LeSetPeriodicAdvertisingEnableView(parent);
    }

    uint8_t GetEnable() const {
        _ASSERT_VALID(valid_);
        return enable_;
    }
    
    uint8_t GetIncludeAdi() const {
        _ASSERT_VALID(valid_);
        return include_adi_;
    }
    
    uint8_t GetAdvertisingHandle() const {
        _ASSERT_VALID(valid_);
        return advertising_handle_;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SET_PERIODIC_ADVERTISING_ENABLE;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetPeriodicAdvertisingEnableView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SET_PERIODIC_ADVERTISING_ENABLE) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 2) {
            return false;
        }
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        enable_ = (chunk0 >> 0) & 0x1;
        include_adi_ = (chunk0 >> 1) & 0x1;
        advertising_handle_ = span.read_le<uint8_t, 1>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t enable_{0};
    uint8_t include_adi_{0};
    uint8_t advertising_handle_{0};

    
};

