class ScanningPhyParameters : public pdl::packet::Builder {
public:
    ~ScanningPhyParameters() override = default;
    ScanningPhyParameters() = default;
    ScanningPhyParameters(ScanningPhyParameters const&) = default;
    ScanningPhyParameters(ScanningPhyParameters&&) = default;
    ScanningPhyParameters& operator=(ScanningPhyParameters const&) = default;
        ScanningPhyParameters(LeScanType le_scan_type, uint16_t le_scan_interval, uint16_t le_scan_window)
        : le_scan_type_(le_scan_type), le_scan_interval_(le_scan_interval), le_scan_window_(le_scan_window) {
    
}

    static bool Parse(pdl::packet::slice& span, ScanningPhyParameters* output) {
        LeScanType le_scan_type_;
        uint16_t le_scan_interval_;
        uint16_t le_scan_window_;
        if (span.size() < 5) {
            return false;
        }
        le_scan_type_ = LeScanType(span.read_le<uint8_t, 1>());
        le_scan_interval_ = span.read_le<uint16_t, 2>();
        le_scan_window_ = span.read_le<uint16_t, 2>();
        *output = ScanningPhyParameters(le_scan_type_, le_scan_interval_, le_scan_window_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(le_scan_type_) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(le_scan_interval_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(le_scan_window_ & 0xffff) << 0));
    }

    size_t GetSize() const override {
        return 5;
    }

    
    std::string ToString() const {
        return "";
    }
    
    LeScanType le_scan_type_{LeScanType::PASSIVE};
    uint16_t le_scan_interval_{0};
    uint16_t le_scan_window_{0};
};

class LeSetExtendedScanParametersView {
public:
    static LeSetExtendedScanParametersView Create(CommandView const& parent) {
        return LeSetExtendedScanParametersView(parent);
    }

    OwnAddressType GetOwnAddressType() const {
        _ASSERT_VALID(valid_);
        return own_address_type_;
    }
    
    LeScanningFilterPolicy GetScanningFilterPolicy() const {
        _ASSERT_VALID(valid_);
        return scanning_filter_policy_;
    }
    
    uint8_t GetScanningPhys() const {
        _ASSERT_VALID(valid_);
        return scanning_phys_;
    }
    
    std::vector<ScanningPhyParameters> GetScanningPhyParameters() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = scanning_phy_parameters_;
        std::vector<ScanningPhyParameters> elements;
        for (;;) {
            ScanningPhyParameters element;
            if (!ScanningPhyParameters::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SET_EXTENDED_SCAN_PARAMETERS;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetExtendedScanParametersView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SET_EXTENDED_SCAN_PARAMETERS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 3) {
            return false;
        }
        own_address_type_ = OwnAddressType(span.read_le<uint8_t, 1>());
        scanning_filter_policy_ = LeScanningFilterPolicy(span.read_le<uint8_t, 1>());
        scanning_phys_ = span.read_le<uint8_t, 1>();
        scanning_phy_parameters_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    OwnAddressType own_address_type_{OwnAddressType::PUBLIC_DEVICE_ADDRESS};
    LeScanningFilterPolicy scanning_filter_policy_{LeScanningFilterPolicy::ACCEPT_ALL};
    uint8_t scanning_phys_{0};
    pdl::packet::slice scanning_phy_parameters_;

    
};

