enum class FilterDuplicates : uint8_t {
    DISABLED = 0x0,
    ENABLED = 0x1,
    RESET_EACH_PERIOD = 0x2,
};

inline std::string FilterDuplicatesText(FilterDuplicates tag) {
    switch (tag) {
        case FilterDuplicates::DISABLED: return "DISABLED";
        case FilterDuplicates::ENABLED: return "ENABLED";
        case FilterDuplicates::RESET_EACH_PERIOD: return "RESET_EACH_PERIOD";
        default:
            return std::string("Unknown FilterDuplicates: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

