class PeriodicAdvertisingOptions : public pdl::packet::Builder {
public:
    ~PeriodicAdvertisingOptions() override = default;
    PeriodicAdvertisingOptions() = default;
    PeriodicAdvertisingOptions(PeriodicAdvertisingOptions const&) = default;
    PeriodicAdvertisingOptions(PeriodicAdvertisingOptions&&) = default;
    PeriodicAdvertisingOptions& operator=(PeriodicAdvertisingOptions const&) = default;
        PeriodicAdvertisingOptions(uint8_t use_periodic_advertiser_list, uint8_t disable_reporting, uint8_t enable_duplicate_filtering)
        : use_periodic_advertiser_list_(use_periodic_advertiser_list), disable_reporting_(disable_reporting), enable_duplicate_filtering_(enable_duplicate_filtering) {
    
}

    static bool Parse(pdl::packet::slice& span, PeriodicAdvertisingOptions* output) {
        uint8_t use_periodic_advertiser_list_;
        uint8_t disable_reporting_;
        uint8_t enable_duplicate_filtering_;
        if (span.size() < 1) {
            return false;
        }
        uint8_t chunk0 = span.read_le<uint8_t, 1>();
        use_periodic_advertiser_list_ = (chunk0 >> 0) & 0x1;
        disable_reporting_ = (chunk0 >> 1) & 0x1;
        enable_duplicate_filtering_ = (chunk0 >> 2) & 0x1;
        *output = PeriodicAdvertisingOptions(use_periodic_advertiser_list_, disable_reporting_, enable_duplicate_filtering_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(use_periodic_advertiser_list_ & 0x1) << 0) | (static_cast<uint8_t>(disable_reporting_ & 0x1) << 1) | (static_cast<uint8_t>(enable_duplicate_filtering_ & 0x1) << 2));
    }

    size_t GetSize() const override {
        return 1;
    }

    
    std::string ToString() const {
        return "";
    }
    
    uint8_t use_periodic_advertiser_list_{0};
    uint8_t disable_reporting_{0};
    uint8_t enable_duplicate_filtering_{0};
};

