enum class PrivacyMode : uint8_t {
    NETWORK = 0x0,
    DEVICE = 0x1,
};

inline std::string PrivacyModeText(PrivacyMode tag) {
    switch (tag) {
        case PrivacyMode::NETWORK: return "NETWORK";
        case PrivacyMode::DEVICE: return "DEVICE";
        default:
            return std::string("Unknown PrivacyMode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

