enum class SyncTransferMode : uint8_t {
    NO_SYNC = 0x0,
    SEND_SYNC_RECEIVED_DISABLE_REPORTS = 0x1,
    SEND_SYNC_RECEIVED_SEND_REPORTS = 0x2,
};

inline std::string SyncTransferModeText(SyncTransferMode tag) {
    switch (tag) {
        case SyncTransferMode::NO_SYNC: return "NO_SYNC";
        case SyncTransferMode::SEND_SYNC_RECEIVED_DISABLE_REPORTS: return "SEND_SYNC_RECEIVED_DISABLE_REPORTS";
        case SyncTransferMode::SEND_SYNC_RECEIVED_SEND_REPORTS: return "SEND_SYNC_RECEIVED_SEND_REPORTS";
        default:
            return std::string("Unknown SyncTransferMode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class CteType : uint8_t {
    AOA_CONSTANT_TONE_EXTENSION = 0x0,
    AOD_CONSTANT_TONE_EXTENSION_ONE_US_SLOTS = 0x1,
    AOD_CONSTANT_TONE_EXTENSION_TWO_US_SLOTS = 0x2,
    NO_CONSTANT_TONE_EXTENSION = 0xff,
};

inline std::string CteTypeText(CteType tag) {
    switch (tag) {
        case CteType::AOA_CONSTANT_TONE_EXTENSION: return "AOA_CONSTANT_TONE_EXTENSION";
        case CteType::AOD_CONSTANT_TONE_EXTENSION_ONE_US_SLOTS: return "AOD_CONSTANT_TONE_EXTENSION_ONE_US_SLOTS";
        case CteType::AOD_CONSTANT_TONE_EXTENSION_TWO_US_SLOTS: return "AOD_CONSTANT_TONE_EXTENSION_TWO_US_SLOTS";
        case CteType::NO_CONSTANT_TONE_EXTENSION: return "NO_CONSTANT_TONE_EXTENSION";
        default:
            return std::string("Unknown CteType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

