    ~LeSetCigParametersBuilder() override = default;
    LeSetCigParametersBuilder() = default;
    LeSetCigParametersBuilder(LeSetCigParametersBuilder const&) = default;
    LeSetCigParametersBuilder(LeSetCigParametersBuilder&&) = default;
