    static std::unique_ptr<LeSetCigParametersCompleteBuilder> Create(uint8_t num_hci_command_packets, ErrorCode status, uint8_t cig_id, std::vector<uint16_t> connection_handle) {
    return std::make_unique<LeSetCigParametersCompleteBuilder>(num_hci_command_packets, status, cig_id, std::move(connection_handle));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::COMMAND_COMPLETE) << 0));
        size_t commandcomplete_payload_size = 3;
        commandcomplete_payload_size += GetConnectionHandleSize();
        size_t event_payload_size = 3;
        event_payload_size += commandcomplete_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(num_hci_command_packets_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::LE_SET_CIG_PARAMETERS) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(status_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(cig_id_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(connection_handle_.size()) << 0));
        for (size_t n = 0; n < connection_handle_.size(); n++) {
            pdl::packet::Builder::write_le<uint16_t, 2>(output, connection_handle_[n]);
        }
    }

