    explicit LeBigCreateSyncView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_BIG_CREATE_SYNC) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t bis_count;
        if (span.size() < 4) {
            return false;
        }
        big_handle_ = span.read_le<uint8_t, 1>();
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        sync_handle_ = (chunk0 >> 0) & 0xfff;
        encryption_ = Enable(span.read_le<uint8_t, 1>());
        if (span.size() < 16 * 1) {
            return false;
        }
        broadcast_code_ = span.subrange(0, 16 * 1);
        span.skip(16 * 1);
        if (span.size() < 4) {
            return false;
        }
        uint8_t chunk1 = span.read_le<uint8_t, 1>();
        mse_ = (chunk1 >> 0) & 0x1f;
        big_sync_timeout_ = span.read_le<uint16_t, 2>();
        bis_count = span.read_le<uint8_t, 1>();
        if (span.size() < bis_count * 1) {
            return false;
        }
        bis_ = span.subrange(0, bis_count * 1);
        span.skip(bis_count * 1);
        return true;
    }

