class LeSetupIsoDataPathView {
public:
    static LeSetupIsoDataPathView Create(CommandView const& parent) {
        return LeSetupIsoDataPathView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    DataPathDirection GetDataPathDirection() const {
        _ASSERT_VALID(valid_);
        return data_path_direction_;
    }
    
    uint8_t GetDataPathId() const {
        _ASSERT_VALID(valid_);
        return data_path_id_;
    }
    
    uint64_t GetCodecId() const {
        _ASSERT_VALID(valid_);
        return codec_id_;
    }
    
    uint32_t GetControllerDelay() const {
        _ASSERT_VALID(valid_);
        return controller_delay_;
    }
    
    std::vector<uint8_t> GetCodecConfiguration() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = codec_configuration_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_SETUP_ISO_DATA_PATH;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeSetupIsoDataPathView(CommandView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.op_code_ != OpCode::LE_SETUP_ISO_DATA_PATH) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t codec_configuration_count;
        if (span.size() < 13) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        data_path_direction_ = DataPathDirection(span.read_le<uint8_t, 1>());
        data_path_id_ = span.read_le<uint8_t, 1>();
        codec_id_ = span.read_le<uint64_t, 5>();
        controller_delay_ = span.read_le<uint32_t, 3>();
        codec_configuration_count = span.read_le<uint8_t, 1>();
        if (span.size() < codec_configuration_count * 1) {
            return false;
        }
        codec_configuration_ = span.subrange(0, codec_configuration_count * 1);
        span.skip(codec_configuration_count * 1);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    DataPathDirection data_path_direction_{DataPathDirection::INPUT};
    uint8_t data_path_id_{0};
    uint64_t codec_id_{0};
    uint32_t controller_delay_{0};
    pdl::packet::slice codec_configuration_;

    
};

class LeSetupIsoDataPathBuilder : public CommandBuilder {
public:
    ~LeSetupIsoDataPathBuilder() override = default;
    LeSetupIsoDataPathBuilder() = default;
    LeSetupIsoDataPathBuilder(LeSetupIsoDataPathBuilder const&) = default;
    LeSetupIsoDataPathBuilder(LeSetupIsoDataPathBuilder&&) = default;
    LeSetupIsoDataPathBuilder& operator=(LeSetupIsoDataPathBuilder const&) = default;
        LeSetupIsoDataPathBuilder(uint16_t connection_handle, DataPathDirection data_path_direction, uint8_t data_path_id, uint64_t codec_id, uint32_t controller_delay, std::vector<uint8_t> codec_configuration)
        : CommandBuilder(OpCode::LE_SETUP_ISO_DATA_PATH, std::vector<uint8_t>{}), connection_handle_(connection_handle), data_path_direction_(data_path_direction), data_path_id_(data_path_id), codec_id_(codec_id), controller_delay_(controller_delay), codec_configuration_(std::move(codec_configuration)) {
    
}
    static std::unique_ptr<LeSetupIsoDataPathBuilder> Create(uint16_t connection_handle, DataPathDirection data_path_direction, uint8_t data_path_id, uint64_t codec_id, uint32_t controller_delay, std::vector<uint8_t> codec_configuration) {
    return std::make_unique<LeSetupIsoDataPathBuilder>(connection_handle, data_path_direction, data_path_id, codec_id, controller_delay, std::move(codec_configuration));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::LE_SETUP_ISO_DATA_PATH) << 0));
        size_t command_payload_size = 13;
        command_payload_size += GetCodecConfigurationSize();
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(command_payload_size) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xfff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(data_path_direction_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(data_path_id_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint64_t, 5>(output, (static_cast<uint64_t>(codec_id_ & 0xffffffffff) << 0));
        pdl::packet::Builder::write_le<uint32_t, 3>(output, (static_cast<uint32_t>(controller_delay_ & 0xffffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(codec_configuration_.size()) << 0));
        output.insert(output.end(), codec_configuration_.begin(), codec_configuration_.end());
    }

    size_t GetSize() const override {
        return GetCodecConfigurationSize() + 16;
    }

    size_t GetCodecConfigurationSize() const {
        return codec_configuration_.size() * 1;
    }
    
    uint16_t connection_handle_{0};
    DataPathDirection data_path_direction_{DataPathDirection::INPUT};
    uint8_t data_path_id_{0};
    uint64_t codec_id_{0};
    uint32_t controller_delay_{0};
    std::vector<uint8_t> codec_configuration_;
};

