enum class RemoveDataPathDirection : uint8_t {
    INPUT = 0x1,
    OUTPUT = 0x2,
    INPUT_AND_OUTPUT = 0x3,
};

inline std::string RemoveDataPathDirectionText(RemoveDataPathDirection tag) {
    switch (tag) {
        case RemoveDataPathDirection::INPUT: return "INPUT";
        case RemoveDataPathDirection::OUTPUT: return "OUTPUT";
        case RemoveDataPathDirection::INPUT_AND_OUTPUT: return "INPUT_AND_OUTPUT";
        default:
            return std::string("Unknown RemoveDataPathDirection: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

