enum class LeHostFeatureBits : uint8_t {
    CONNECTED_ISO_STREAM_HOST_SUPPORT = 0x20,
    CONNECTION_SUBRATING_HOST_SUPPORT = 0x26,
};

inline std::string LeHostFeatureBitsText(LeHostFeatureBits tag) {
    switch (tag) {
        case LeHostFeatureBits::CONNECTED_ISO_STREAM_HOST_SUPPORT: return "CONNECTED_ISO_STREAM_HOST_SUPPORT";
        case LeHostFeatureBits::CONNECTION_SUBRATING_HOST_SUPPORT: return "CONNECTION_SUBRATING_HOST_SUPPORT";
        default:
            return std::string("Unknown LeHostFeatureBits: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

