enum class PhyWithCodedSpecified : uint8_t {
    LE_1M = 0x1,
    LE_2M = 0x2,
    LE_CODED_S_8 = 0x3,
    LE_CODED_S_2 = 0x4,
};

inline std::string PhyWithCodedSpecifiedText(PhyWithCodedSpecified tag) {
    switch (tag) {
        case PhyWithCodedSpecified::LE_1M: return "LE_1M";
        case PhyWithCodedSpecified::LE_2M: return "LE_2M";
        case PhyWithCodedSpecified::LE_CODED_S_8: return "LE_CODED_S_8";
        case PhyWithCodedSpecified::LE_CODED_S_2: return "LE_CODED_S_2";
        default:
            return std::string("Unknown PhyWithCodedSpecified: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

