class InquiryResponse : public pdl::packet::Builder {
public:
    ~InquiryResponse() override = default;
    InquiryResponse() = default;
    InquiryResponse(InquiryResponse const&) = default;
    InquiryResponse(InquiryResponse&&) = default;
    InquiryResponse& operator=(InquiryResponse const&) = default;
        InquiryResponse(Address bd_addr, PageScanRepetitionMode page_scan_repetition_mode, uint32_t class_of_device, uint16_t clock_offset)
        : bd_addr_(std::move(bd_addr)), page_scan_repetition_mode_(page_scan_repetition_mode), class_of_device_(class_of_device), clock_offset_(clock_offset) {
    
}

    static bool Parse(pdl::packet::slice& span, InquiryResponse* output) {
        Address bd_addr_;
        PageScanRepetitionMode page_scan_repetition_mode_;
        uint32_t class_of_device_;
        uint16_t clock_offset_;
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 8) {
            return false;
        }
        page_scan_repetition_mode_ = PageScanRepetitionMode(span.read_le<uint8_t, 1>());
        span.skip(1); // skip reserved fields
        span.skip(1); // skip reserved fields
        class_of_device_ = span.read_le<uint32_t, 3>();
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        clock_offset_ = (chunk0 >> 0) & 0x7fff;
        *output = InquiryResponse(std::move(bd_addr_), page_scan_repetition_mode_, class_of_device_, clock_offset_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        bd_addr_.Serialize(output);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(page_scan_repetition_mode_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, 0);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, 0);
        pdl::packet::Builder::write_le<uint32_t, 3>(output, (static_cast<uint32_t>(class_of_device_ & 0xffffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(clock_offset_ & 0x7fff) << 0));
    }

    size_t GetSize() const override {
        return 14;
    }

    
    std::string ToString() const {
        return "";
    }
    
    Address bd_addr_;
    PageScanRepetitionMode page_scan_repetition_mode_{PageScanRepetitionMode::R0};
    uint32_t class_of_device_{0};
    uint16_t clock_offset_{0};
};

class InquiryResultView {
public:
    static InquiryResultView Create(EventView const& parent) {
        return InquiryResultView(parent);
    }

    std::vector<InquiryResponse> GetResponses() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = responses_;
        std::vector<InquiryResponse> elements;
        for (;;) {
            InquiryResponse element;
            if (!InquiryResponse::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::INQUIRY_RESULT;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit InquiryResultView(EventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(EventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.event_code_ != EventCode::INQUIRY_RESULT) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t responses_count;
        if (span.size() < 1) {
            return false;
        }
        responses_count = span.read_le<uint8_t, 1>();
        if (span.size() < responses_count * 14) {
            return false;
        }
        responses_ = span.subrange(0, responses_count * 14);
        span.skip(responses_count * 14);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    pdl::packet::slice responses_;

    
};

