        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::INQUIRY_RESULT) << 0));
        size_t event_payload_size = 1;
        event_payload_size += GetResponsesSize();
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(responses_.size()) << 0));
        for (size_t n = 0; n < responses_.size(); n++) {
            responses_[n].Serialize(output);
        }
