class LoopbackCommandBuilder : public EventBuilder {
public:
    ~LoopbackCommandBuilder() override = default;
    LoopbackCommandBuilder() = default;
    LoopbackCommandBuilder(LoopbackCommandBuilder const&) = default;
    LoopbackCommandBuilder(LoopbackCommandBuilder&&) = default;
    LoopbackCommandBuilder& operator=(LoopbackCommandBuilder const&) = default;
        explicit LoopbackCommandBuilder(std::vector<uint8_t> payload)
        : EventBuilder(EventCode::LOOPBACK_COMMAND, std::vector<uint8_t>{}) {
    payload_ = std::move(payload);
}
    static std::unique_ptr<LoopbackCommandBuilder> Create(std::vector<uint8_t> payload) {
    return std::make_unique<LoopbackCommandBuilder>(std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::LOOPBACK_COMMAND) << 0));
        size_t event_payload_size = 0;
        event_payload_size += payload_.size();
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 2;
    }

    
    
};

