inline std::string ScoAirModeText(ScoAirMode tag) {
    switch (tag) {
        case ScoAirMode::ULAW_LOG: return "ULAW_LOG";
        case ScoAirMode::ALAW_LOG: return "ALAW_LOG";
        case ScoAirMode::CVSD: return "CVSD";
        case ScoAirMode::TRANSPARENT: return "TRANSPARENT";
        default:
            return std::string("Unknown ScoAirMode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

