enum class FlushablePacketType : uint8_t {
    AUTOMATICALLY_FLUSHABLE_ONLY = 0x0,
};

inline std::string FlushablePacketTypeText(FlushablePacketType tag) {
    switch (tag) {
        case FlushablePacketType::AUTOMATICALLY_FLUSHABLE_ONLY: return "AUTOMATICALLY_FLUSHABLE_ONLY";
        default:
            return std::string("Unknown FlushablePacketType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

