class EnhancedFlushStatusBuilder : public CommandStatusBuilder {
public:
    ~EnhancedFlushStatusBuilder() override = default;
    EnhancedFlushStatusBuilder() = default;
    EnhancedFlushStatusBuilder(EnhancedFlushStatusBuilder const&) = default;
    EnhancedFlushStatusBuilder(EnhancedFlushStatusBuilder&&) = default;
    EnhancedFlushStatusBuilder& operator=(EnhancedFlushStatusBuilder const&) = default;
        EnhancedFlushStatusBuilder(ErrorCode status, uint8_t num_hci_command_packets)
        : CommandStatusBuilder(status, num_hci_command_packets, OpCode::ENHANCED_FLUSH, std::vector<uint8_t>{}) {
    
}
    static std::unique_ptr<EnhancedFlushStatusBuilder> Create(ErrorCode status, uint8_t num_hci_command_packets) {
    return std::make_unique<EnhancedFlushStatusBuilder>(status, num_hci_command_packets);
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::COMMAND_STATUS) << 0));
        size_t commandstatus_payload_size = 0;
        size_t event_payload_size = 4;
        event_payload_size += commandstatus_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(status_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(num_hci_command_packets_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::ENHANCED_FLUSH) << 0));
    }

    size_t GetSize() const override {
        return 6;
    }

    
    
};

