class LeLongTermKeyRequestView {
public:
    static LeLongTermKeyRequestView Create(LeMetaEventView const& parent) {
        return LeLongTermKeyRequestView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    std::array<uint8_t, 8> GetRandomNumber() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = random_number_;
        std::array<uint8_t, 8> elements;
        for (int n = 0; n < 8; n++) {
            elements[n] = span.read_le<uint8_t, 1>();
        }
        return elements;
    }
    
    uint16_t GetEncryptedDiversifier() const {
        _ASSERT_VALID(valid_);
        return encrypted_diversifier_;
    }
    
    EventCode GetEventCode() const {
        return EventCode::LE_META_EVENT;
    }
    
    SubeventCode GetSubeventCode() const {
        return SubeventCode::LONG_TERM_KEY_REQUEST;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeLongTermKeyRequestView(LeMetaEventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeMetaEventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.subevent_code_ != SubeventCode::LONG_TERM_KEY_REQUEST) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 2) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        if (span.size() < 8 * 1) {
            return false;
        }
        random_number_ = span.subrange(0, 8 * 1);
        span.skip(8 * 1);
        if (span.size() < 2) {
            return false;
        }
        encrypted_diversifier_ = span.read_le<uint16_t, 2>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    pdl::packet::slice random_number_;
    uint16_t encrypted_diversifier_{0};

    
};

