class LeEnhancedConnectionCompleteView {
public:
    static LeEnhancedConnectionCompleteView Create(LeMetaEventView const& parent) {
        return LeEnhancedConnectionCompleteView(parent);
    }

    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    Role GetRole() const {
        _ASSERT_VALID(valid_);
        return role_;
    }
    
    AddressType GetPeerAddressType() const {
        _ASSERT_VALID(valid_);
        return peer_address_type_;
    }
    
    Address const& GetPeerAddress() const {
        _ASSERT_VALID(valid_);
        return peer_address_;
    }
    
    Address const& GetLocalResolvablePrivateAddress() const {
        _ASSERT_VALID(valid_);
        return local_resolvable_private_address_;
    }
    
    Address const& GetPeerResolvablePrivateAddress() const {
        _ASSERT_VALID(valid_);
        return peer_resolvable_private_address_;
    }
    
    uint16_t GetConnectionInterval() const {
        _ASSERT_VALID(valid_);
        return connection_interval_;
    }
    
    uint16_t GetPeripheralLatency() const {
        _ASSERT_VALID(valid_);
        return peripheral_latency_;
    }
    
    uint16_t GetSupervisionTimeout() const {
        _ASSERT_VALID(valid_);
        return supervision_timeout_;
    }
    
    ClockAccuracy GetCentralClockAccuracy() const {
        _ASSERT_VALID(valid_);
        return central_clock_accuracy_;
    }
    
    EventCode GetEventCode() const {
        return EventCode::LE_META_EVENT;
    }
    
    SubeventCode GetSubeventCode() const {
        return SubeventCode::ENHANCED_CONNECTION_COMPLETE;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeEnhancedConnectionCompleteView(LeMetaEventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeMetaEventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.subevent_code_ != SubeventCode::ENHANCED_CONNECTION_COMPLETE) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 5) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        role_ = Role(span.read_le<uint8_t, 1>());
        peer_address_type_ = AddressType(span.read_le<uint8_t, 1>());
        if (!Address::Parse(span, &peer_address_)) {
            return false;
        }
        if (!Address::Parse(span, &local_resolvable_private_address_)) {
            return false;
        }
        if (!Address::Parse(span, &peer_resolvable_private_address_)) {
            return false;
        }
        if (span.size() < 7) {
            return false;
        }
        connection_interval_ = span.read_le<uint16_t, 2>();
        peripheral_latency_ = span.read_le<uint16_t, 2>();
        supervision_timeout_ = span.read_le<uint16_t, 2>();
        central_clock_accuracy_ = ClockAccuracy(span.read_le<uint8_t, 1>());
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    uint16_t connection_handle_{0};
    Role role_{Role::CENTRAL};
    AddressType peer_address_type_{AddressType::PUBLIC_DEVICE_ADDRESS};
    Address peer_address_;
    Address local_resolvable_private_address_;
    Address peer_resolvable_private_address_;
    uint16_t connection_interval_{0};
    uint16_t peripheral_latency_{0};
    uint16_t supervision_timeout_{0};
    ClockAccuracy central_clock_accuracy_{ClockAccuracy::PPM_500};

    
};

