        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(status_) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xfff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(role_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(peer_address_type_) << 0));
        peer_address_.Serialize(output);
        local_resolvable_private_address_.Serialize(output);
        peer_resolvable_private_address_.Serialize(output);
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_interval_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(peripheral_latency_ & 0xffff) << 0));
