    LeDirectedAdvertisingReportBuilder& operator=(LeDirectedAdvertisingReportBuilder const&) = default;
        explicit LeDirectedAdvertisingReportBuilder(std::vector<LeDirectedAdvertisingResponse> responses)
        : LeMetaEventBuilder(SubeventCode::DIRECTED_ADVERTISING_REPORT, std::vector<uint8_t>{}), responses_(std::move(responses)) {
    
}
