    LePhyUpdateCompleteBuilder& operator=(LePhyUpdateCompleteBuilder const&) = default;
        LePhyUpdateCompleteBuilder(ErrorCode status, uint16_t connection_handle, PhyType tx_phy, PhyType rx_phy)
        : LeMetaEventBuilder(SubeventCode::PHY_UPDATE_COMPLETE, std::vector<uint8_t>{}), status_(status), connection_handle_(connection_handle), tx_phy_(tx_phy), rx_phy_(rx_phy) {
    
}
