enum class ChannelSelectionAlgorithm : uint8_t {
    ALGORITHM_1 = 0x0,
    ALGORITHM_2 = 0x1,
};

inline std::string ChannelSelectionAlgorithmText(ChannelSelectionAlgorithm tag) {
    switch (tag) {
        case ChannelSelectionAlgorithm::ALGORITHM_1: return "ALGORITHM_1";
        case ChannelSelectionAlgorithm::ALGORITHM_2: return "ALGORITHM_2";
        default:
            return std::string("Unknown ChannelSelectionAlgorithm: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

