        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        service_data_ = span.read_le<uint16_t, 2>();
        uint16_t chunk1 = span.read_le<uint16_t, 2>();
        sync_handle_ = (chunk1 >> 0) & 0xfff;
        uint8_t chunk2 = span.read_le<uint8_t, 1>();
        advertising_sid_ = (chunk2 >> 0) & 0xf;
        advertiser_address_type_ = AddressType(span.read_le<uint8_t, 1>());
