class LeBigSyncEstablishedView {
public:
    static LeBigSyncEstablishedView Create(LeMetaEventView const& parent) {
        return LeBigSyncEstablishedView(parent);
    }

    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    uint8_t GetBigHandle() const {
        _ASSERT_VALID(valid_);
        return big_handle_;
    }
    
    uint32_t GetTransportLatencyBig() const {
        _ASSERT_VALID(valid_);
        return transport_latency_big_;
    }
    
    uint8_t GetNse() const {
        _ASSERT_VALID(valid_);
        return nse_;
    }
    
    uint8_t GetBn() const {
        _ASSERT_VALID(valid_);
        return bn_;
    }
    
    uint8_t GetPto() const {
        _ASSERT_VALID(valid_);
        return pto_;
    }
    
    uint8_t GetIrc() const {
        _ASSERT_VALID(valid_);
        return irc_;
    }
    
    uint16_t GetMaxPdu() const {
        _ASSERT_VALID(valid_);
        return max_pdu_;
    }
    
    uint16_t GetIsoInterval() const {
        _ASSERT_VALID(valid_);
        return iso_interval_;
    }
    
    std::vector<uint16_t> GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = connection_handle_;
        std::vector<uint16_t> elements;
        while (span.size() >= 2) {
            elements.push_back(span.read_le<uint16_t, 2>());
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::LE_META_EVENT;
    }
    
    SubeventCode GetSubeventCode() const {
        return SubeventCode::BIG_SYNC_ESTABLISHED;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeBigSyncEstablishedView(LeMetaEventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeMetaEventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.subevent_code_ != SubeventCode::BIG_SYNC_ESTABLISHED) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t connection_handle_size;
        if (span.size() < 14) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        big_handle_ = span.read_le<uint8_t, 1>();
        transport_latency_big_ = span.read_le<uint32_t, 3>();
        nse_ = span.read_le<uint8_t, 1>();
        bn_ = span.read_le<uint8_t, 1>();
        pto_ = span.read_le<uint8_t, 1>();
        irc_ = span.read_le<uint8_t, 1>();
        max_pdu_ = span.read_le<uint16_t, 2>();
        iso_interval_ = span.read_le<uint16_t, 2>();
        connection_handle_size = span.read_le<uint8_t, 1>();
        if (span.size() < connection_handle_size) {
            return false;
        }
        connection_handle_ = span.subrange(0, connection_handle_size);
        span.skip(connection_handle_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    uint8_t big_handle_{0};
    uint32_t transport_latency_big_{0};
    uint8_t nse_{0};
    uint8_t bn_{0};
    uint8_t pto_{0};
    uint8_t irc_{0};
    uint16_t max_pdu_{0};
    uint16_t iso_interval_{0};
    pdl::packet::slice connection_handle_;

    
};

class LeBigSyncEstablishedBuilder : public LeMetaEventBuilder {
public:
    ~LeBigSyncEstablishedBuilder() override = default;
    LeBigSyncEstablishedBuilder() = default;
    LeBigSyncEstablishedBuilder(LeBigSyncEstablishedBuilder const&) = default;
    LeBigSyncEstablishedBuilder(LeBigSyncEstablishedBuilder&&) = default;
    LeBigSyncEstablishedBuilder& operator=(LeBigSyncEstablishedBuilder const&) = default;
        LeBigSyncEstablishedBuilder(ErrorCode status, uint8_t big_handle, uint32_t transport_latency_big, uint8_t nse, uint8_t bn, uint8_t pto, uint8_t irc, uint16_t max_pdu, uint16_t iso_interval, std::vector<uint16_t> connection_handle)
        : LeMetaEventBuilder(SubeventCode::BIG_SYNC_ESTABLISHED, std::vector<uint8_t>{}), status_(status), big_handle_(big_handle), transport_latency_big_(transport_latency_big), nse_(nse), bn_(bn), pto_(pto), irc_(irc), max_pdu_(max_pdu), iso_interval_(iso_interval), connection_handle_(std::move(connection_handle)) {
    
}
    static std::unique_ptr<LeBigSyncEstablishedBuilder> Create(ErrorCode status, uint8_t big_handle, uint32_t transport_latency_big, uint8_t nse, uint8_t bn, uint8_t pto, uint8_t irc, uint16_t max_pdu, uint16_t iso_interval, std::vector<uint16_t> connection_handle) {
    return std::make_unique<LeBigSyncEstablishedBuilder>(status, big_handle, transport_latency_big, nse, bn, pto, irc, max_pdu, iso_interval, std::move(connection_handle));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::LE_META_EVENT) << 0));
        size_t lemetaevent_payload_size = 14;
        lemetaevent_payload_size += GetConnectionHandleSize();
        size_t event_payload_size = 1;
        event_payload_size += lemetaevent_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(SubeventCode::BIG_SYNC_ESTABLISHED) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(status_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(big_handle_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint32_t, 3>(output, (static_cast<uint32_t>(transport_latency_big_ & 0xffffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(nse_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(bn_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(pto_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(irc_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(max_pdu_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(iso_interval_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(GetConnectionHandleSize()) << 0));
        for (size_t n = 0; n < connection_handle_.size(); n++) {
            pdl::packet::Builder::write_le<uint16_t, 2>(output, connection_handle_[n]);
        }
    }

    size_t GetSize() const override {
        return GetConnectionHandleSize() + 17;
    }

    size_t GetConnectionHandleSize() const {
        return connection_handle_.size() * 2;
    }
    
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    uint8_t big_handle_{0};
    uint32_t transport_latency_big_{0};
    uint8_t nse_{0};
    uint8_t bn_{0};
    uint8_t pto_{0};
    uint8_t irc_{0};
    uint16_t max_pdu_{0};
    uint16_t iso_interval_{0};
    std::vector<uint16_t> connection_handle_;
};

