enum class IsoPacketBoundaryFlag : uint8_t {
    FIRST_FRAGMENT = 0x0,
    CONTINUATION_FRAGMENT = 0x1,
    COMPLETE_SDU = 0x2,
    LAST_FRAGMENT = 0x3,
};

inline std::string IsoPacketBoundaryFlagText(IsoPacketBoundaryFlag tag) {
    switch (tag) {
        case IsoPacketBoundaryFlag::FIRST_FRAGMENT: return "FIRST_FRAGMENT";
        case IsoPacketBoundaryFlag::CONTINUATION_FRAGMENT: return "CONTINUATION_FRAGMENT";
        case IsoPacketBoundaryFlag::COMPLETE_SDU: return "COMPLETE_SDU";
        case IsoPacketBoundaryFlag::LAST_FRAGMENT: return "LAST_FRAGMENT";
        default:
            return std::string("Unknown IsoPacketBoundaryFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class TimeStampFlag : uint8_t {
    NOT_PRESENT = 0x0,
    PRESENT = 0x1,
};

inline std::string TimeStampFlagText(TimeStampFlag tag) {
    switch (tag) {
        case TimeStampFlag::NOT_PRESENT: return "NOT_PRESENT";
        case TimeStampFlag::PRESENT: return "PRESENT";
        default:
            return std::string("Unknown TimeStampFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class IsoView {
public:
    static IsoView Create(pdl::packet::slice const& parent) {
        return IsoView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    IsoPacketBoundaryFlag GetPbFlag() const {
        _ASSERT_VALID(valid_);
        return pb_flag_;
    }
    
    TimeStampFlag GetTsFlag() const {
        _ASSERT_VALID(valid_);
        return ts_flag_;
    }
    
    std::vector<uint8_t> GetPayload() const {
        _ASSERT_VALID(valid_);
        return payload_.bytes();
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit IsoView(pdl::packet::slice const& parent)
          : bytes_(parent) {
        valid_ = Parse(parent);
    }

    bool Parse(pdl::packet::slice const& parent) {
        // Parse packet field values.
        pdl::packet::slice span = parent;
        uint16_t _payload__size;
        if (span.size() < 4) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        connection_handle_ = (chunk0 >> 0) & 0xfff;
        pb_flag_ = IsoPacketBoundaryFlag((chunk0 >> 12) & 0x3);
        ts_flag_ = TimeStampFlag((chunk0 >> 14) & 0x1);
        uint16_t chunk1 = span.read_le<uint16_t, 2>();
        _payload__size = (chunk1 >> 0) & 0x3fff;
        if (span.size() < _payload__size) {
            return false;
        }
        payload_ = span.subrange(0, _payload__size);
        span.skip(_payload__size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    IsoPacketBoundaryFlag pb_flag_{IsoPacketBoundaryFlag::FIRST_FRAGMENT};
    TimeStampFlag ts_flag_{TimeStampFlag::NOT_PRESENT};
    pdl::packet::slice payload_;

    friend class IsoWithTimestampView;
    friend class IsoWithoutTimestampView;
};

class IsoBuilder : public pdl::packet::Builder {
public:
    ~IsoBuilder() override = default;
    IsoBuilder() = default;
    IsoBuilder(IsoBuilder const&) = default;
    IsoBuilder(IsoBuilder&&) = default;
    IsoBuilder& operator=(IsoBuilder const&) = default;
        IsoBuilder(uint16_t connection_handle, IsoPacketBoundaryFlag pb_flag, TimeStampFlag ts_flag, std::vector<uint8_t> payload)
        : connection_handle_(connection_handle), pb_flag_(pb_flag), ts_flag_(ts_flag), payload_(std::move(payload)) {
    
}
    static std::unique_ptr<IsoBuilder> Create(uint16_t connection_handle, IsoPacketBoundaryFlag pb_flag, TimeStampFlag ts_flag, std::vector<uint8_t> payload) {
    return std::make_unique<IsoBuilder>(connection_handle, pb_flag, ts_flag, std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xfff) << 0) | (static_cast<uint16_t>(pb_flag_) << 12) | (static_cast<uint16_t>(ts_flag_) << 14));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(payload_.size()) << 0));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 4;
    }

    
    uint16_t connection_handle_{0};
    IsoPacketBoundaryFlag pb_flag_{IsoPacketBoundaryFlag::FIRST_FRAGMENT};
    TimeStampFlag ts_flag_{TimeStampFlag::NOT_PRESENT};
    std::vector<uint8_t> payload_;
};

enum class IsoPacketStatusFlag : uint8_t {
    VALID = 0x0,
    POSSIBLY_INVALID = 0x1,
    LOST_DATA = 0x2,
};

inline std::string IsoPacketStatusFlagText(IsoPacketStatusFlag tag) {
    switch (tag) {
        case IsoPacketStatusFlag::VALID: return "VALID";
        case IsoPacketStatusFlag::POSSIBLY_INVALID: return "POSSIBLY_INVALID";
        case IsoPacketStatusFlag::LOST_DATA: return "LOST_DATA";
        default:
            return std::string("Unknown IsoPacketStatusFlag: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class IsoWithTimestampView {
public:
    static IsoWithTimestampView Create(IsoView const& parent) {
        return IsoWithTimestampView(parent);
    }

    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    IsoPacketBoundaryFlag GetPbFlag() const {
        _ASSERT_VALID(valid_);
        return pb_flag_;
    }
    
    uint32_t GetTimeStamp() const {
        _ASSERT_VALID(valid_);
        return time_stamp_;
    }
    
    uint16_t GetPacketSequenceNumber() const {
        _ASSERT_VALID(valid_);
        return packet_sequence_number_;
    }
    
    uint16_t GetIsoSduLength() const {
        _ASSERT_VALID(valid_);
        return iso_sdu_length_;
    }
    
    IsoPacketStatusFlag GetPacketStatusFlag() const {
        _ASSERT_VALID(valid_);
        return packet_status_flag_;
    }
    
    std::vector<uint8_t> GetPayload() const {
        _ASSERT_VALID(valid_);
        return payload_.bytes();
    }
    
    TimeStampFlag GetTsFlag() const {
        return TimeStampFlag::PRESENT;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit IsoWithTimestampView(IsoView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(IsoView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        connection_handle_ = parent.connection_handle_;
        pb_flag_ = parent.pb_flag_;
        
        if (parent.ts_flag_ != TimeStampFlag::PRESENT) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 8) {
            return false;
        }
        time_stamp_ = span.read_le<uint32_t, 4>();
        packet_sequence_number_ = span.read_le<uint16_t, 2>();
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        iso_sdu_length_ = (chunk0 >> 0) & 0xfff;
        packet_status_flag_ = IsoPacketStatusFlag((chunk0 >> 14) & 0x3);
        payload_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t connection_handle_{0};
    IsoPacketBoundaryFlag pb_flag_{IsoPacketBoundaryFlag::FIRST_FRAGMENT};
    uint32_t time_stamp_{0};
    uint16_t packet_sequence_number_{0};
    uint16_t iso_sdu_length_{0};
    IsoPacketStatusFlag packet_status_flag_{IsoPacketStatusFlag::VALID};
    pdl::packet::slice payload_;

    
};

class IsoWithTimestampBuilder : public IsoBuilder {
public:
    ~IsoWithTimestampBuilder() override = default;
    IsoWithTimestampBuilder() = default;
    IsoWithTimestampBuilder(IsoWithTimestampBuilder const&) = default;
    IsoWithTimestampBuilder(IsoWithTimestampBuilder&&) = default;
    IsoWithTimestampBuilder& operator=(IsoWithTimestampBuilder const&) = default;
        IsoWithTimestampBuilder(uint16_t connection_handle, IsoPacketBoundaryFlag pb_flag, uint32_t time_stamp, uint16_t packet_sequence_number, uint16_t iso_sdu_length, IsoPacketStatusFlag packet_status_flag, std::vector<uint8_t> payload)
        : IsoBuilder(connection_handle, pb_flag, TimeStampFlag::PRESENT, std::vector<uint8_t>{}), time_stamp_(time_stamp), packet_sequence_number_(packet_sequence_number), iso_sdu_length_(iso_sdu_length), packet_status_flag_(packet_status_flag) {
    payload_ = std::move(payload);
}
    static std::unique_ptr<IsoWithTimestampBuilder> Create(uint16_t connection_handle, IsoPacketBoundaryFlag pb_flag, uint32_t time_stamp, uint16_t packet_sequence_number, uint16_t iso_sdu_length, IsoPacketStatusFlag packet_status_flag, std::vector<uint8_t> payload) {
    return std::make_unique<IsoWithTimestampBuilder>(connection_handle, pb_flag, time_stamp, packet_sequence_number, iso_sdu_length, packet_status_flag, std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xfff) << 0) | (static_cast<uint16_t>(pb_flag_) << 12) | (static_cast<uint16_t>(TimeStampFlag::PRESENT) << 14));
        size_t iso_payload_size = 8;
        iso_payload_size += payload_.size();
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(iso_payload_size) << 0));
        pdl::packet::Builder::write_le<uint32_t, 4>(output, (static_cast<uint32_t>(time_stamp_ & 0xffffffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(packet_sequence_number_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(iso_sdu_length_ & 0xfff) << 0) | (static_cast<uint16_t>(packet_status_flag_) << 14));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 12;
    }

    
    uint32_t time_stamp_{0};
    uint16_t packet_sequence_number_{0};
    uint16_t iso_sdu_length_{0};
    IsoPacketStatusFlag packet_status_flag_{IsoPacketStatusFlag::VALID};
};

