class LeGetVendorCapabilitiesCompleteView {
public:
    static LeGetVendorCapabilitiesCompleteView Create(CommandCompleteView const& parent) {
        return LeGetVendorCapabilitiesCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    std::vector<uint8_t> GetVendorCapabilities() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = vendor_capabilities_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::LE_GET_VENDOR_CAPABILITIES;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeGetVendorCapabilitiesCompleteView(CommandCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(CommandCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        
        if (parent.command_op_code_ != OpCode::LE_GET_VENDOR_CAPABILITIES) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 1) {
            return false;
        }
        status_ = ErrorCode(span.read_le<uint8_t, 1>());
        vendor_capabilities_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    pdl::packet::slice vendor_capabilities_;

    
};

