public:
    ~LeGetVendorCapabilitiesCompleteBuilder() override = default;
    LeGetVendorCapabilitiesCompleteBuilder() = default;
    LeGetVendorCapabilitiesCompleteBuilder(LeGetVendorCapabilitiesCompleteBuilder const&) = default;
