enum class BatchScanDataRead : uint8_t {
    TRUNCATED_MODE_DATA = 0x1,
    FULL_MODE_DATA = 0x2,
};

inline std::string BatchScanDataReadText(BatchScanDataRead tag) {
    switch (tag) {
        case BatchScanDataRead::TRUNCATED_MODE_DATA: return "TRUNCATED_MODE_DATA";
        case BatchScanDataRead::FULL_MODE_DATA: return "FULL_MODE_DATA";
        default:
            return std::string("Unknown BatchScanDataRead: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

