class TruncatedResult : public pdl::packet::Builder {
public:
    ~TruncatedResult() override = default;
    TruncatedResult() = default;
    TruncatedResult(TruncatedResult const&) = default;
    TruncatedResult(TruncatedResult&&) = default;
    TruncatedResult& operator=(TruncatedResult const&) = default;
        TruncatedResult(Address bd_addr, AddressType address_type, uint8_t tx_power, uint8_t rssi, uint16_t timestamp)
        : bd_addr_(std::move(bd_addr)), address_type_(address_type), tx_power_(tx_power), rssi_(rssi), timestamp_(timestamp) {
    
}

    static bool Parse(pdl::packet::slice& span, TruncatedResult* output) {
        Address bd_addr_;
        AddressType address_type_;
        uint8_t tx_power_;
        uint8_t rssi_;
        uint16_t timestamp_;
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 5) {
            return false;
        }
        address_type_ = AddressType(span.read_le<uint8_t, 1>());
        tx_power_ = span.read_le<uint8_t, 1>();
        rssi_ = span.read_le<uint8_t, 1>();
        timestamp_ = span.read_le<uint16_t, 2>();
        *output = TruncatedResult(std::move(bd_addr_), address_type_, tx_power_, rssi_, timestamp_);
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        bd_addr_.Serialize(output);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(address_type_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(tx_power_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(rssi_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(timestamp_ & 0xffff) << 0));
    }

    size_t GetSize() const override {
        return 11;
    }

    
    std::string ToString() const {
        return "";
    }
    
    Address bd_addr_;
    AddressType address_type_{AddressType::PUBLIC_DEVICE_ADDRESS};
    uint8_t tx_power_{0};
    uint8_t rssi_{0};
    uint16_t timestamp_{0};
};

class LeBatchScanReadTruncatedResultParametersCompleteView {
public:
    static LeBatchScanReadTruncatedResultParametersCompleteView Create(LeBatchScanReadResultParametersCompleteView const& parent) {
        return LeBatchScanReadTruncatedResultParametersCompleteView(parent);
    }

    uint8_t GetNumHciCommandPackets() const {
        _ASSERT_VALID(valid_);
        return num_hci_command_packets_;
    }
    
    ErrorCode GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    std::vector<TruncatedResult> GetResults() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = results_;
        std::vector<TruncatedResult> elements;
        for (;;) {
            TruncatedResult element;
            if (!TruncatedResult::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::COMMAND_COMPLETE;
    }
    
    OpCode GetCommandOpCode() const {
        return OpCode::LE_BATCH_SCAN;
    }
    
    BatchScanOpcode GetBatchScanOpcode() const {
        return BatchScanOpcode::READ_RESULT_PARAMETERS;
    }
    
    BatchScanDataRead GetBatchScanDataRead() const {
        return BatchScanDataRead::TRUNCATED_MODE_DATA;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeBatchScanReadTruncatedResultParametersCompleteView(LeBatchScanReadResultParametersCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeBatchScanReadResultParametersCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        status_ = parent.status_;
        
        if (parent.batch_scan_data_read_ != BatchScanDataRead::TRUNCATED_MODE_DATA) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t results_count;
        if (span.size() < 1) {
            return false;
        }
        results_count = span.read_le<uint8_t, 1>();
        if (span.size() < results_count * 11) {
            return false;
        }
        results_ = span.subrange(0, results_count * 11);
        span.skip(results_count * 11);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t num_hci_command_packets_{0};
    ErrorCode status_{ErrorCode::STATUS_UNKNOWN};
    pdl::packet::slice results_;

    
};

