enum class ApcfOpcode : uint8_t {
    ENABLE = 0x0,
    SET_FILTERING_PARAMETERS = 0x1,
    BROADCASTER_ADDRESS = 0x2,
    SERVICE_UUID = 0x3,
    SERVICE_SOLICITATION_UUID = 0x4,
    LOCAL_NAME = 0x5,
    MANUFACTURER_DATA = 0x6,
    SERVICE_DATA = 0x7,
    TRANSPORT_DISCOVERY_SERVICE = 0x8,
    AD_TYPE_FILTER = 0x9,
    READ_EXTENDED_FEATURES = 0xff,
};

inline std::string ApcfOpcodeText(ApcfOpcode tag) {
    switch (tag) {
        case ApcfOpcode::ENABLE: return "ENABLE";
        case ApcfOpcode::SET_FILTERING_PARAMETERS: return "SET_FILTERING_PARAMETERS";
        case ApcfOpcode::BROADCASTER_ADDRESS: return "BROADCASTER_ADDRESS";
        case ApcfOpcode::SERVICE_UUID: return "SERVICE_UUID";
        case ApcfOpcode::SERVICE_SOLICITATION_UUID: return "SERVICE_SOLICITATION_UUID";
        case ApcfOpcode::LOCAL_NAME: return "LOCAL_NAME";
        case ApcfOpcode::MANUFACTURER_DATA: return "MANUFACTURER_DATA";
        case ApcfOpcode::SERVICE_DATA: return "SERVICE_DATA";
        case ApcfOpcode::TRANSPORT_DISCOVERY_SERVICE: return "TRANSPORT_DISCOVERY_SERVICE";
        case ApcfOpcode::AD_TYPE_FILTER: return "AD_TYPE_FILTER";
        case ApcfOpcode::READ_EXTENDED_FEATURES: return "READ_EXTENDED_FEATURES";
        default:
            return std::string("Unknown ApcfOpcode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

