enum class ApcfAction : uint8_t {
    ADD = 0x0,
    DELETE = 0x1,
    CLEAR = 0x2,
};

inline std::string ApcfActionText(ApcfAction tag) {
    switch (tag) {
        case ApcfAction::ADD: return "ADD";
        case ApcfAction::DELETE: return "DELETE";
        case ApcfAction::CLEAR: return "CLEAR";
        default:
            return std::string("Unknown ApcfAction: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class DeliveryMode : uint8_t {
    IMMEDIATE = 0x0,
    ONFOUND = 0x1,
    BATCHED = 0x2,
};

inline std::string DeliveryModeText(DeliveryMode tag) {
    switch (tag) {
        case DeliveryMode::IMMEDIATE: return "IMMEDIATE";
        case DeliveryMode::ONFOUND: return "ONFOUND";
        case DeliveryMode::BATCHED: return "BATCHED";
        default:
            return std::string("Unknown DeliveryMode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class ApcfFeatureSelection : uint8_t {
    BROADCASTER_ADDRESS = 0x0,
    SERVICE_DATA_CHANGE = 0x1,
    SERVICE_UUID = 0x2,
    SERVICE_SOLICITATION_UUID = 0x3,
    LOCAL_NAME = 0x4,
    MANUFACTURER_DATA = 0x5,
    SERVICE_DATA = 0x6,
    TRANSPORT_DISCOVERY_DATA = 0x7,
    AD_TYPE = 0x8,
};

inline std::string ApcfFeatureSelectionText(ApcfFeatureSelection tag) {
    switch (tag) {
        case ApcfFeatureSelection::BROADCASTER_ADDRESS: return "BROADCASTER_ADDRESS";
        case ApcfFeatureSelection::SERVICE_DATA_CHANGE: return "SERVICE_DATA_CHANGE";
        case ApcfFeatureSelection::SERVICE_UUID: return "SERVICE_UUID";
        case ApcfFeatureSelection::SERVICE_SOLICITATION_UUID: return "SERVICE_SOLICITATION_UUID";
        case ApcfFeatureSelection::LOCAL_NAME: return "LOCAL_NAME";
        case ApcfFeatureSelection::MANUFACTURER_DATA: return "MANUFACTURER_DATA";
        case ApcfFeatureSelection::SERVICE_DATA: return "SERVICE_DATA";
        case ApcfFeatureSelection::TRANSPORT_DISCOVERY_DATA: return "TRANSPORT_DISCOVERY_DATA";
        case ApcfFeatureSelection::AD_TYPE: return "AD_TYPE";
        default:
            return std::string("Unknown ApcfFeatureSelection: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

