protected:
    explicit LeApcfSetFilteringParametersCompleteView(LeApcfCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeApcfCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        status_ = parent.status_;
        
        if (parent.apcf_opcode_ != ApcfOpcode::SET_FILTERING_PARAMETERS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 2) {
            return false;
        }
        apcf_action_ = ApcfAction(span.read_le<uint8_t, 1>());
        apcf_available_spaces_ = span.read_le<uint8_t, 1>();
        return true;
    }

