enum class ApcfApplicationAddressType : uint8_t {
    PUBLIC = 0x0,
    RANDOM = 0x1,
    NOT_APPLICABLE = 0x2,
};

inline std::string ApcfApplicationAddressTypeText(ApcfApplicationAddressType tag) {
    switch (tag) {
        case ApcfApplicationAddressType::PUBLIC: return "PUBLIC";
        case ApcfApplicationAddressType::RANDOM: return "RANDOM";
        case ApcfApplicationAddressType::NOT_APPLICABLE: return "NOT_APPLICABLE";
        default:
            return std::string("Unknown ApcfApplicationAddressType: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

