class LeApcfAdTypeFilterView {
public:
    static LeApcfAdTypeFilterView Create(LeApcfView const& parent) {
        return LeApcfAdTypeFilterView(parent);
    }

    ApcfAction GetApcfAction() const {
        _ASSERT_VALID(valid_);
        return apcf_action_;
    }
    
    uint8_t GetApcfFilterIndex() const {
        _ASSERT_VALID(valid_);
        return apcf_filter_index_;
    }
    
    uint8_t GetApcfAdType() const {
        _ASSERT_VALID(valid_);
        return apcf_ad_type_;
    }
    
    std::vector<uint8_t> GetApcfAdData() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = apcf_ad_data_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    std::vector<uint8_t> GetApcfAdDataMask() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = apcf_ad_data_mask_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    OpCode GetOpCode() const {
        return OpCode::LE_APCF;
    }
    
    ApcfOpcode GetApcfOpcode() const {
        return ApcfOpcode::AD_TYPE_FILTER;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeApcfAdTypeFilterView(LeApcfView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeApcfView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.apcf_opcode_ != ApcfOpcode::AD_TYPE_FILTER) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t apcf_ad_data_size;
        if (span.size() < 4) {
            return false;
        }
        apcf_action_ = ApcfAction(span.read_le<uint8_t, 1>());
        apcf_filter_index_ = span.read_le<uint8_t, 1>();
        apcf_ad_type_ = span.read_le<uint8_t, 1>();
        apcf_ad_data_size = span.read_le<uint8_t, 1>();
        if (span.size() < apcf_ad_data_size) {
            return false;
        }
        apcf_ad_data_ = span.subrange(0, apcf_ad_data_size);
        span.skip(apcf_ad_data_size);
        apcf_ad_data_mask_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    ApcfAction apcf_action_{ApcfAction::ADD};
    uint8_t apcf_filter_index_{0};
    uint8_t apcf_ad_type_{0};
    pdl::packet::slice apcf_ad_data_;
    pdl::packet::slice apcf_ad_data_mask_;

    
};

