        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(OpCode::LE_APCF) << 0));
        size_t leapcf_payload_size = 4;
        leapcf_payload_size += GetApcfAdDataSize();
        leapcf_payload_size += GetApcfAdDataMaskSize();
        size_t command_payload_size = 1;
        command_payload_size += leapcf_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(command_payload_size) << 0));
