protected:
    explicit LeApcfReadExtendedFeaturesCompleteView(LeApcfCompleteView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(LeApcfCompleteView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        num_hci_command_packets_ = parent.num_hci_command_packets_;
        status_ = parent.status_;
        
        if (parent.apcf_opcode_ != ApcfOpcode::READ_EXTENDED_FEATURES) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 2) {
            return false;
        }
        uint16_t chunk0 = span.read_le<uint16_t, 2>();
        transport_discovery_data_filter_ = (chunk0 >> 0) & 0x1;
        ad_type_filter_ = (chunk0 >> 1) & 0x1;
        return true;
    }

