enum class AdvertiserState : uint8_t {
    ADVERTISER_FOUND = 0x0,
    ADVERTISER_LOST = 0x1,
};

inline std::string AdvertiserStateText(AdvertiserState tag) {
    switch (tag) {
        case AdvertiserState::ADVERTISER_FOUND: return "ADVERTISER_FOUND";
        case AdvertiserState::ADVERTISER_LOST: return "ADVERTISER_LOST";
        default:
            return std::string("Unknown AdvertiserState: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class AdvtInfoPresent : uint8_t {
    ADVT_INFO_PRESENT = 0x0,
    ADVT_INFO_NOT_PRESENT = 0x1,
};

inline std::string AdvtInfoPresentText(AdvtInfoPresent tag) {
    switch (tag) {
        case AdvtInfoPresent::ADVT_INFO_PRESENT: return "ADVT_INFO_PRESENT";
        case AdvtInfoPresent::ADVT_INFO_NOT_PRESENT: return "ADVT_INFO_NOT_PRESENT";
        default:
            return std::string("Unknown AdvtInfoPresent: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class AdvtInfo : public pdl::packet::Builder {
public:
    ~AdvtInfo() override = default;
    AdvtInfo() = default;
    AdvtInfo(AdvtInfo const&) = default;
    AdvtInfo(AdvtInfo&&) = default;
    AdvtInfo& operator=(AdvtInfo const&) = default;
        AdvtInfo(uint8_t tx_power, uint8_t rssi, uint16_t timestamp, std::vector<uint8_t> adv_packet, std::vector<uint8_t> scan_data_resp)
        : tx_power_(tx_power), rssi_(rssi), timestamp_(timestamp), adv_packet_(std::move(adv_packet)), scan_data_resp_(std::move(scan_data_resp)) {
    
}

    static bool Parse(pdl::packet::slice& span, AdvtInfo* output) {
        uint8_t tx_power_;
        uint8_t rssi_;
        uint16_t timestamp_;
        uint8_t adv_packet_size;
        std::vector<uint8_t> adv_packet_;
        uint8_t scan_data_resp_size;
        std::vector<uint8_t> scan_data_resp_;
        if (span.size() < 5) {
            return false;
        }
        tx_power_ = span.read_le<uint8_t, 1>();
        rssi_ = span.read_le<uint8_t, 1>();
        timestamp_ = span.read_le<uint16_t, 2>();
        adv_packet_size = span.read_le<uint8_t, 1>();
        if (span.size() < adv_packet_size) {
            return false;
        }
        {
        pdl::packet::slice temp_span = span.subrange(0, adv_packet_size);
        span.skip(adv_packet_size);
        while (temp_span.size() > 0) {
            if (temp_span.size() < 1) {
                return false;
            }
            adv_packet_.push_back(temp_span.read_le<uint8_t, 1>());
        }
        }
        if (span.size() < 1) {
            return false;
        }
        scan_data_resp_size = span.read_le<uint8_t, 1>();
        if (span.size() < scan_data_resp_size) {
            return false;
        }
        {
        pdl::packet::slice temp_span = span.subrange(0, scan_data_resp_size);
        span.skip(scan_data_resp_size);
        while (temp_span.size() > 0) {
            if (temp_span.size() < 1) {
                return false;
            }
            scan_data_resp_.push_back(temp_span.read_le<uint8_t, 1>());
        }
        }
        *output = AdvtInfo(tx_power_, rssi_, timestamp_, std::move(adv_packet_), std::move(scan_data_resp_));
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(tx_power_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(rssi_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(timestamp_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(GetAdvPacketSize()) << 0));
        output.insert(output.end(), adv_packet_.begin(), adv_packet_.end());
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(GetScanDataRespSize()) << 0));
        output.insert(output.end(), scan_data_resp_.begin(), scan_data_resp_.end());
    }

    size_t GetSize() const override {
        return 6 + (
    GetAdvPacketSize() +
        GetScanDataRespSize()
    );
    }

    size_t GetAdvPacketSize() const {
        return adv_packet_.size() * 1;
    }
    
    size_t GetScanDataRespSize() const {
        return scan_data_resp_.size() * 1;
    }
    
    std::string ToString() const {
        return "";
    }
    
    uint8_t tx_power_{0};
    uint8_t rssi_{0};
    uint16_t timestamp_{0};
    std::vector<uint8_t> adv_packet_;
    std::vector<uint8_t> scan_data_resp_;
};

class LeAdvertisementTrackingEventView {
public:
    static LeAdvertisementTrackingEventView Create(VendorSpecificEventView const& parent) {
        return LeAdvertisementTrackingEventView(parent);
    }

    uint8_t GetApcfFilterIndex() const {
        _ASSERT_VALID(valid_);
        return apcf_filter_index_;
    }
    
    AdvertiserState GetAdvertiserState() const {
        _ASSERT_VALID(valid_);
        return advertiser_state_;
    }
    
    AdvtInfoPresent GetAdvtInfoPresent() const {
        _ASSERT_VALID(valid_);
        return advt_info_present_;
    }
    
    Address const& GetAdvertiserAddress() const {
        _ASSERT_VALID(valid_);
        return advertiser_address_;
    }
    
    PeerAddressType GetAdvertiserAddressType() const {
        _ASSERT_VALID(valid_);
        return advertiser_address_type_;
    }
    
    std::vector<AdvtInfo> GetAdvtInfo() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = advt_info_;
        std::vector<AdvtInfo> elements;
        for (;;) {
            AdvtInfo element;
            if (!AdvtInfo::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::VENDOR_SPECIFIC;
    }
    
    VseSubeventCode GetSubeventCode() const {
        return VseSubeventCode::LE_ADVERTISEMENT_TRACKING;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit LeAdvertisementTrackingEventView(VendorSpecificEventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(VendorSpecificEventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.subevent_code_ != VseSubeventCode::LE_ADVERTISEMENT_TRACKING) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 3) {
            return false;
        }
        apcf_filter_index_ = span.read_le<uint8_t, 1>();
        advertiser_state_ = AdvertiserState(span.read_le<uint8_t, 1>());
        advt_info_present_ = AdvtInfoPresent(span.read_le<uint8_t, 1>());
        if (!Address::Parse(span, &advertiser_address_)) {
            return false;
        }
        if (span.size() < 1) {
            return false;
        }
        advertiser_address_type_ = PeerAddressType(span.read_le<uint8_t, 1>());
        advt_info_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t apcf_filter_index_{0};
    AdvertiserState advertiser_state_{AdvertiserState::ADVERTISER_FOUND};
    AdvtInfoPresent advt_info_present_{AdvtInfoPresent::ADVT_INFO_PRESENT};
    Address advertiser_address_;
    PeerAddressType advertiser_address_type_{PeerAddressType::PUBLIC_DEVICE_OR_IDENTITY_ADDRESS};
    pdl::packet::slice advt_info_;

    
};

class LeAdvertisementTrackingEventBuilder : public VendorSpecificEventBuilder {
public:
    ~LeAdvertisementTrackingEventBuilder() override = default;
    LeAdvertisementTrackingEventBuilder() = default;
    LeAdvertisementTrackingEventBuilder(LeAdvertisementTrackingEventBuilder const&) = default;
    LeAdvertisementTrackingEventBuilder(LeAdvertisementTrackingEventBuilder&&) = default;
    LeAdvertisementTrackingEventBuilder& operator=(LeAdvertisementTrackingEventBuilder const&) = default;
        LeAdvertisementTrackingEventBuilder(uint8_t apcf_filter_index, AdvertiserState advertiser_state, AdvtInfoPresent advt_info_present, Address advertiser_address, PeerAddressType advertiser_address_type, std::vector<AdvtInfo> advt_info)
        : VendorSpecificEventBuilder(VseSubeventCode::LE_ADVERTISEMENT_TRACKING, std::vector<uint8_t>{}), apcf_filter_index_(apcf_filter_index), advertiser_state_(advertiser_state), advt_info_present_(advt_info_present), advertiser_address_(std::move(advertiser_address)), advertiser_address_type_(advertiser_address_type), advt_info_(std::move(advt_info)) {
    
}
    static std::unique_ptr<LeAdvertisementTrackingEventBuilder> Create(uint8_t apcf_filter_index, AdvertiserState advertiser_state, AdvtInfoPresent advt_info_present, Address advertiser_address, PeerAddressType advertiser_address_type, std::vector<AdvtInfo> advt_info) {
    return std::make_unique<LeAdvertisementTrackingEventBuilder>(apcf_filter_index, advertiser_state, advt_info_present, std::move(advertiser_address), advertiser_address_type, std::move(advt_info));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(EventCode::VENDOR_SPECIFIC) << 0));
        size_t vendorspecificevent_payload_size = 10;
        vendorspecificevent_payload_size += GetAdvtInfoSize();
        size_t event_payload_size = 1;
        event_payload_size += vendorspecificevent_payload_size;
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(event_payload_size) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(VseSubeventCode::LE_ADVERTISEMENT_TRACKING) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(apcf_filter_index_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(advertiser_state_) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(advt_info_present_) << 0));
        advertiser_address_.Serialize(output);
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(advertiser_address_type_) << 0));
        for (size_t n = 0; n < advt_info_.size(); n++) {
            advt_info_[n].Serialize(output);
        }
    }

    size_t GetSize() const override {
        return GetAdvtInfoSize() + 13;
    }

    size_t GetAdvtInfoSize() const {
        size_t array_size = 0;
        for (size_t n = 0; n < advt_info_.size(); n++) {
            array_size += advt_info_[n].GetSize();
        }
        return array_size;
    }
    
    uint8_t apcf_filter_index_{0};
    AdvertiserState advertiser_state_{AdvertiserState::ADVERTISER_FOUND};
    AdvtInfoPresent advt_info_present_{AdvtInfoPresent::ADVT_INFO_PRESENT};
    Address advertiser_address_;
    PeerAddressType advertiser_address_type_{PeerAddressType::PUBLIC_DEVICE_OR_IDENTITY_ADDRESS};
    std::vector<AdvtInfo> advt_info_;
};

