class ControllerDebugInfoEventView {
public:
    static ControllerDebugInfoEventView Create(VendorSpecificEventView const& parent) {
        return ControllerDebugInfoEventView(parent);
    }

    uint16_t GetDebugBlockByteOffsetStart() const {
        _ASSERT_VALID(valid_);
        return debug_block_byte_offset_start_;
    }
    
    uint8_t GetLastBlock() const {
        _ASSERT_VALID(valid_);
        return last_block_;
    }
    
    std::vector<uint8_t> GetDebugData() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = debug_data_;
        std::vector<uint8_t> elements;
        while (span.size() >= 1) {
            elements.push_back(span.read_le<uint8_t, 1>());
        }
        return elements;
    }
    
    EventCode GetEventCode() const {
        return EventCode::VENDOR_SPECIFIC;
    }
    
    VseSubeventCode GetSubeventCode() const {
        return VseSubeventCode::CONTROLLER_DEBUG_INFO;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit ControllerDebugInfoEventView(VendorSpecificEventView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(VendorSpecificEventView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.subevent_code_ != VseSubeventCode::CONTROLLER_DEBUG_INFO) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint16_t debug_data_size;
        if (span.size() < 5) {
            return false;
        }
        debug_block_byte_offset_start_ = span.read_le<uint16_t, 2>();
        last_block_ = span.read_le<uint8_t, 1>();
        debug_data_size = span.read_le<uint16_t, 2>();
        if (span.size() < debug_data_size) {
            return false;
        }
        debug_data_ = span.subrange(0, debug_data_size);
        span.skip(debug_data_size);
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint16_t debug_block_byte_offset_start_{0};
    uint8_t last_block_{0};
    pdl::packet::slice debug_data_;

    
};

