class MsftLeMonitorAdvConditionPattern : public pdl::packet::Builder {
public:
    ~MsftLeMonitorAdvConditionPattern() override = default;
    MsftLeMonitorAdvConditionPattern() = default;
    MsftLeMonitorAdvConditionPattern(MsftLeMonitorAdvConditionPattern const&) = default;
    MsftLeMonitorAdvConditionPattern(MsftLeMonitorAdvConditionPattern&&) = default;
    MsftLeMonitorAdvConditionPattern& operator=(MsftLeMonitorAdvConditionPattern const&) = default;
        MsftLeMonitorAdvConditionPattern(uint8_t ad_type, uint8_t start_of_pattern, std::vector<uint8_t> pattern)
        : ad_type_(ad_type), start_of_pattern_(start_of_pattern), pattern_(std::move(pattern)) {
    
}

    static bool Parse(pdl::packet::slice& span, MsftLeMonitorAdvConditionPattern* output) {
        uint8_t pattern_size;
        uint8_t ad_type_;
        uint8_t start_of_pattern_;
        std::vector<uint8_t> pattern_;
        if (span.size() < 3) {
            return false;
        }
        pattern_size = span.read_le<uint8_t, 1>();
        ad_type_ = span.read_le<uint8_t, 1>();
        start_of_pattern_ = span.read_le<uint8_t, 1>();
        pattern_size = pattern_size - +2;
        if (span.size() < pattern_size) {
            return false;
        }
        {
        pdl::packet::slice temp_span = span.subrange(0, pattern_size);
        span.skip(pattern_size);
        while (temp_span.size() > 0) {
            if (temp_span.size() < 1) {
                return false;
            }
            pattern_.push_back(temp_span.read_le<uint8_t, 1>());
        }
        }
        *output = MsftLeMonitorAdvConditionPattern(ad_type_, start_of_pattern_, std::move(pattern_));
        return true;
    }

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(GetPatternSize() + +2) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(ad_type_ & 0xff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(start_of_pattern_ & 0xff) << 0));
        output.insert(output.end(), pattern_.begin(), pattern_.end());
    }

    size_t GetSize() const override {
        return GetPatternSize() + 3;
    }

    size_t GetPatternSize() const {
        return pattern_.size() * 1;
    }
    
    std::string ToString() const {
        return "";
    }
    
    uint8_t ad_type_{0};
    uint8_t start_of_pattern_{0};
    std::vector<uint8_t> pattern_;
};

class MsftLeMonitorAdvConditionPatternsView {
public:
    static MsftLeMonitorAdvConditionPatternsView Create(MsftLeMonitorAdvView const& parent) {
        return MsftLeMonitorAdvConditionPatternsView(parent);
    }

    OpCode GetOpCode() const {
        _ASSERT_VALID(valid_);
        return op_code_;
    }
    
    uint8_t GetRssiThresholdHigh() const {
        _ASSERT_VALID(valid_);
        return rssi_threshold_high_;
    }
    
    uint8_t GetRssiThresholdLow() const {
        _ASSERT_VALID(valid_);
        return rssi_threshold_low_;
    }
    
    uint8_t GetRssiThresholdLowTimeInterval() const {
        _ASSERT_VALID(valid_);
        return rssi_threshold_low_time_interval_;
    }
    
    uint8_t GetRssiSamplingPeriod() const {
        _ASSERT_VALID(valid_);
        return rssi_sampling_period_;
    }
    
    std::vector<MsftLeMonitorAdvConditionPattern> GetPatterns() const {
        _ASSERT_VALID(valid_);
        pdl::packet::slice span = patterns_;
        std::vector<MsftLeMonitorAdvConditionPattern> elements;
        for (;;) {
            MsftLeMonitorAdvConditionPattern element;
            if (!MsftLeMonitorAdvConditionPattern::Parse(span, &element)) {
                break;
            }
            elements.emplace_back(std::move(element));
        }
        return elements;
    }
    
    MsftSubcommandOpcode GetSubcommandOpcode() const {
        return MsftSubcommandOpcode::MSFT_LE_MONITOR_ADV;
    }
    
    MsftLeMonitorAdvConditionType GetConditionType() const {
        return MsftLeMonitorAdvConditionType::MSFT_CONDITION_TYPE_PATTERNS;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit MsftLeMonitorAdvConditionPatternsView(MsftLeMonitorAdvView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(MsftLeMonitorAdvView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        // Copy parent field values.
        op_code_ = parent.op_code_;
        rssi_threshold_high_ = parent.rssi_threshold_high_;
        rssi_threshold_low_ = parent.rssi_threshold_low_;
        rssi_threshold_low_time_interval_ = parent.rssi_threshold_low_time_interval_;
        rssi_sampling_period_ = parent.rssi_sampling_period_;
        
        if (parent.condition_type_ != MsftLeMonitorAdvConditionType::MSFT_CONDITION_TYPE_PATTERNS) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        uint8_t patterns_count;
        if (span.size() < 1) {
            return false;
        }
        patterns_count = span.read_le<uint8_t, 1>();
        {
        pdl::packet::slice temp_span = span;
        for (size_t n = 0; n < patterns_count; n++) {
            MsftLeMonitorAdvConditionPattern element;
            if (!MsftLeMonitorAdvConditionPattern::Parse(temp_span, &element)) {
                return false;
            }
        }
        patterns_ = span.subrange(0, span.size() - temp_span.size());
        span.skip(patterns_.size());
        }
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    OpCode op_code_{OpCode::NONE};
    uint8_t rssi_threshold_high_{0};
    uint8_t rssi_threshold_low_{0};
    uint8_t rssi_threshold_low_time_interval_{0};
    uint8_t rssi_sampling_period_{0};
    pdl::packet::slice patterns_;

    
};

