enum class MsftEventCode : uint8_t {
    MSFT_RSSI_EVENT = 0x1,
    MSFT_LE_MONITOR_DEVICE_EVENT = 0x2,
};

inline std::string MsftEventCodeText(MsftEventCode tag) {
    switch (tag) {
        case MsftEventCode::MSFT_RSSI_EVENT: return "MSFT_RSSI_EVENT";
        case MsftEventCode::MSFT_LE_MONITOR_DEVICE_EVENT: return "MSFT_LE_MONITOR_DEVICE_EVENT";
        default:
            return std::string("Unknown MsftEventCode: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

enum class MsftEventStatus : uint8_t {
    MSFT_EVENT_STATUS_SUCCESS = 0x0,
    MSFT_EVENT_STATUS_FAILURE = 0x1,
};

inline std::string MsftEventStatusText(MsftEventStatus tag) {
    switch (tag) {
        case MsftEventStatus::MSFT_EVENT_STATUS_SUCCESS: return "MSFT_EVENT_STATUS_SUCCESS";
        case MsftEventStatus::MSFT_EVENT_STATUS_FAILURE: return "MSFT_EVENT_STATUS_FAILURE";
        default:
            return std::string("Unknown MsftEventStatus: " +
                   std::to_string(static_cast<uint64_t>(tag)));
    }
}

class MsftEventPayloadView {
public:
    static MsftEventPayloadView Create(pdl::packet::slice const& parent) {
        return MsftEventPayloadView(parent);
    }

    MsftEventCode GetMsftEventCode() const {
        _ASSERT_VALID(valid_);
        return msft_event_code_;
    }
    
    std::vector<uint8_t> GetPayload() const {
        _ASSERT_VALID(valid_);
        return payload_.bytes();
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit MsftEventPayloadView(pdl::packet::slice const& parent)
          : bytes_(parent) {
        valid_ = Parse(parent);
    }

    bool Parse(pdl::packet::slice const& parent) {
        // Parse packet field values.
        pdl::packet::slice span = parent;
        if (span.size() < 1) {
            return false;
        }
        msft_event_code_ = MsftEventCode(span.read_le<uint8_t, 1>());
        payload_ = span;
        span.clear();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    MsftEventCode msft_event_code_{MsftEventCode::MSFT_RSSI_EVENT};
    pdl::packet::slice payload_;

    friend class MsftRssiEventPayloadView;
    friend class MsftLeMonitorDeviceEventPayloadView;
};

class MsftEventPayloadBuilder : public pdl::packet::Builder {
public:
    ~MsftEventPayloadBuilder() override = default;
    MsftEventPayloadBuilder() = default;
    MsftEventPayloadBuilder(MsftEventPayloadBuilder const&) = default;
    MsftEventPayloadBuilder(MsftEventPayloadBuilder&&) = default;
    MsftEventPayloadBuilder& operator=(MsftEventPayloadBuilder const&) = default;
        MsftEventPayloadBuilder(MsftEventCode msft_event_code, std::vector<uint8_t> payload)
        : msft_event_code_(msft_event_code), payload_(std::move(payload)) {
    
}
    static std::unique_ptr<MsftEventPayloadBuilder> Create(MsftEventCode msft_event_code, std::vector<uint8_t> payload) {
    return std::make_unique<MsftEventPayloadBuilder>(msft_event_code, std::move(payload));
}

    void Serialize(std::vector<uint8_t>& output) const override {
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(msft_event_code_) << 0));
        output.insert(output.end(), payload_.begin(), payload_.end());
    }

    size_t GetSize() const override {
        return payload_.size() + 1;
    }

    
    MsftEventCode msft_event_code_{MsftEventCode::MSFT_RSSI_EVENT};
    std::vector<uint8_t> payload_;
};

class MsftRssiEventPayloadView {
public:
    static MsftRssiEventPayloadView Create(MsftEventPayloadView const& parent) {
        return MsftRssiEventPayloadView(parent);
    }

    MsftEventStatus GetStatus() const {
        _ASSERT_VALID(valid_);
        return status_;
    }
    
    uint16_t GetConnectionHandle() const {
        _ASSERT_VALID(valid_);
        return connection_handle_;
    }
    
    uint8_t GetRssi() const {
        _ASSERT_VALID(valid_);
        return rssi_;
    }
    
    MsftEventCode GetMsftEventCode() const {
        return MsftEventCode::MSFT_RSSI_EVENT;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit MsftRssiEventPayloadView(MsftEventPayloadView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(MsftEventPayloadView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.msft_event_code_ != MsftEventCode::MSFT_RSSI_EVENT) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 4) {
            return false;
        }
        status_ = MsftEventStatus(span.read_le<uint8_t, 1>());
        connection_handle_ = span.read_le<uint16_t, 2>();
        rssi_ = span.read_le<uint8_t, 1>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    MsftEventStatus status_{MsftEventStatus::MSFT_EVENT_STATUS_SUCCESS};
    uint16_t connection_handle_{0};
    uint8_t rssi_{0};

    
};

