        pdl::packet::Builder::write_le<uint16_t, 2>(output, (static_cast<uint16_t>(connection_handle_ & 0xffff) << 0));
        pdl::packet::Builder::write_le<uint8_t, 1>(output, (static_cast<uint8_t>(rssi_ & 0xff) << 0));
