class MsftLeMonitorDeviceEventPayloadView {
public:
    static MsftLeMonitorDeviceEventPayloadView Create(MsftEventPayloadView const& parent) {
        return MsftLeMonitorDeviceEventPayloadView(parent);
    }

    uint8_t GetAddressType() const {
        _ASSERT_VALID(valid_);
        return address_type_;
    }
    
    Address const& GetBdAddr() const {
        _ASSERT_VALID(valid_);
        return bd_addr_;
    }
    
    uint8_t GetMonitorHandle() const {
        _ASSERT_VALID(valid_);
        return monitor_handle_;
    }
    
    uint8_t GetMonitorState() const {
        _ASSERT_VALID(valid_);
        return monitor_state_;
    }
    
    MsftEventCode GetMsftEventCode() const {
        return MsftEventCode::MSFT_LE_MONITOR_DEVICE_EVENT;
    }
    
    
    std::string ToString() const {
        return "";
    }
    

    bool IsValid() const {
        return valid_;
    }

    pdl::packet::slice bytes() const {
        return bytes_;
    }

protected:
    explicit MsftLeMonitorDeviceEventPayloadView(MsftEventPayloadView const& parent)
          : bytes_(parent.bytes_) {
        valid_ = Parse(parent);
    }

    bool Parse(MsftEventPayloadView const& parent) {
        // Check validity of parent packet.
        if (!parent.IsValid()) {
            return false;
        }
        
        if (parent.msft_event_code_ != MsftEventCode::MSFT_LE_MONITOR_DEVICE_EVENT) {
            return false;
        }
        
        // Parse packet field values.
        pdl::packet::slice span = parent.payload_;
        if (span.size() < 1) {
            return false;
        }
        address_type_ = span.read_le<uint8_t, 1>();
        if (!Address::Parse(span, &bd_addr_)) {
            return false;
        }
        if (span.size() < 2) {
            return false;
        }
        monitor_handle_ = span.read_le<uint8_t, 1>();
        monitor_state_ = span.read_le<uint8_t, 1>();
        return true;
    }

    bool valid_{false};
    pdl::packet::slice bytes_;
    uint8_t address_type_{0};
    Address bd_addr_;
    uint8_t monitor_handle_{0};
    uint8_t monitor_state_{0};

    
};

